const chapter2Scenes=[
 {id:"arbeitszeit-start",title:"Arbeitszeit · Einstieg",html:`<section class="scene editorial-bg editorial-people"><div class="photo-split"><div><p class="eyebrow">BLOCK 1 · KAPITEL 2 · ARBEITSZEIT</p><h1>Wann arbeiten wir – und wer bestimmt darüber?</h1><p class="lead">Arbeitszeit ist mehr als eine Zahl. Sie verteilt <b>Zeit, Autonomie, Belastung und Teilhabe.</b></p><div class="pillrow"><span class="pill">DAUER</span><span class="pill">LAGE</span><span class="pill">AUTONOMIE</span><span class="pill">PLANBARKEIT</span></div></div><div class="photo-panel"><img src="https://images.pexels.com/photos/3184465/pexels-photo-3184465.jpeg?auto=compress&cs=tinysrgb&w=1200" alt="Menschen bei der Arbeit"><div class="photo-caption">Kapitel 2 · Arbeitszeit</div></div></div></section>`},

 {id:"arbeitszeit-realitaet",title:"Deutschland 2025",html:`<section class="scene"><p class="eyebrow">ARBEITSZEIT IN DEUTSCHLAND · 2025</p><h2>34 Stunden im Schnitt – aber der Durchschnitt verdeckt große Unterschiede.</h2><div class="stat-grid"><div class="stat-card"><b>39,9 h</b><span>Vollzeitbeschäftigte<br>pro Woche</span></div><div class="stat-card"><b>21,3 h</b><span>Teilzeitbeschäftigte<br>pro Woche</span></div><div class="stat-card accent"><b>34,0 h</b><span>abhängig Beschäftigte<br>insgesamt</span></div></div><p class="takeaway">Die Frage ist nicht nur: <b>Wie lange arbeiten wir?</b> Sondern auch: Wer kann seine Arbeitszeit gestalten?</p><div class="lecture-source">Quelle: Destatis, Mikrozensus 2025 (Erstergebnisse), veröffentlicht 27.05.2026</div><div class="source-row mode-only-learning"><a href="https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/05/PD26_N035_13.html" target="_blank" rel="noopener">Destatis · Daten für 2025 ↗</a><span>Population: abhängig Beschäftigte in Deutschland</span></div></section>`},

 {id:"teilzeit",title:"Teilzeit & Gender",html:`<section class="scene"><div class="photo-split"><div><p class="eyebrow">TEILZEIT · DEUTSCHLAND 2025</p><h2>Teilzeit ist weiterhin stark nach Geschlecht verteilt.</h2><div class="gender-bars"><div><span>Frauen</span><b>50,6 %</b><i style="--w:50.6%"></i></div><div><span>Männer</span><b>14,3 %</b><i style="--w:14.3%"></i></div></div><p class="lead">Bei beiden Geschlechtern erreichte die Teilzeitquote 2025 einen neuen Höchststand.</p><p class="question">Diskussion: <b>Ist Teilzeit Ausdruck von Autonomie – oder von ungleich verteilten Rahmenbedingungen?</b></p><div class="source-row mode-only-learning"><a href="https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/05/PD26_N035_13.html" target="_blank" rel="noopener">Destatis · 2026 ↗</a></div></div><div class="photo-panel"><img src="https://images.pexels.com/photos/3768146/pexels-photo-3768146.jpeg?auto=compress&cs=tinysrgb&w=1200" alt="Berufstätige Frau am Laptop"><div class="photo-caption">Arbeitszeitmodelle wirken in Lebensrealitäten.</div></div></div></section>`},

 {id:"teilzeit-definitionen",title:"Warum Zahlen variieren",html:`<section class="scene"><p class="eyebrow">DATEN LESEN LERNEN</p><h2>31,9 % oder 39,9 % Teilzeit? Beides kann korrekt sein.</h2><div class="compare"><div class="card"><span class="mini-label">DESTATIS · MIKROZENSUS</span><strong>31,9 %</strong><p class="source-prompt">Originalquelle untersuchen ↗</p></div><div class="card"><span class="mini-label">IAB · ARBEITSZEITRECHNUNG</span><strong>39,9 %</strong><p class="source-prompt">Originalquelle untersuchen ↗</p></div></div><div class="research-task"><b>🔎 Rechercheauftrag · Zweiergruppen · 7 Minuten</b><span>1. Öffnen Sie beide Originalquellen. 2. Klären Sie: Welche Population wird gezählt? Wie wird „Teilzeit“ abgegrenzt? 3. Entscheiden Sie: Welche Zahl ist für die Aussage „Anteil der abhängig Beschäftigten in Teilzeit“ passend – und warum? 4. Formulieren Sie eine korrekte Überschrift für beide Zahlen.</span><em>Präsentation: 2–3 Gruppen, je 60 Sekunden. Danach gemeinsame Auflösung.</em></div><div class="solution-wrap"><button type="button" class="solution-toggle">Lösung / Einordnung anzeigen</button><div class="solution-box" hidden><h4>Auflösung</h4><p><b>Beide Werte können korrekt sein</b>, weil sie aus unterschiedlichen statistischen Konzepten stammen.</p><p><b>Destatis – 31,9 %:</b> Mikrozensus; Anteil der Teilzeitbeschäftigten an den abhängig Beschäftigten 2025.</p><p><b>IAB – 39,9 %:</b> IAB-Arbeitszeitrechnung; die IAB-Abgrenzung zählt reguläre Teilzeit und ausschließlich geringfügig Beschäftigte zur Teilzeit.</p><p><b>Entscheidend:</b> Eine Prozentzahl ist nur interpretierbar, wenn Grundgesamtheit und Definition mitgenannt werden.</p></div></div><div class="lecture-source">Quellen: Destatis, Mikrozensus 2025 · IAB-Arbeitszeitrechnung 2025</div><div class="source-row mode-only-learning"><a href="https://iab.de/ergebnisse-der-iab-arbeitszeitrechnung-fuer-das-jahr-2025/" target="_blank" rel="noopener">IAB · Arbeitszeitrechnung 2025 ↗</a><a href="https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/05/PD26_N035_13.html" target="_blank" rel="noopener">Destatis ↗</a></div></section>`},

 {id:"wuensche-eu",title:"Arbeitszeitwünsche EU",html:`<section class="scene editorial-bg editorial-people"><div class="photo-split"><div><p class="eyebrow">EUROPA · EWCS 2024</p><h2>Jede dritte beschäftigte Person in der EU würde lieber weniger arbeiten.</h2><div class="big-number">33 %</div><p class="lead">möchten weniger Stunden arbeiten. <b>56 %</b> möchten ihre aktuelle Stundenzahl beibehalten.</p><p class="micro">2015 wollten 27 % weniger arbeiten – 2024 waren es 33 %.</p><div class="source-row mode-only-learning"><a href="https://www.eurofound.europa.eu/en/publications/all/european-working-conditions-survey-2024-overview-report" target="_blank" rel="noopener">Eurofound · EWCS 2024 ↗</a></div></div><div class="photo-panel"><img src="https://images.pexels.com/photos/3760067/pexels-photo-3760067.jpeg?auto=compress&cs=tinysrgb&w=1200" alt="Menschen in Arbeitssituation"><div class="photo-caption">Arbeitszeitwünsche sind nicht überall gleich.</div></div></div></section>`},

 {id:"flexibilitaet",title:"Flexibilität ≠ Autonomie",html:`<section class="scene"><p class="eyebrow">FLEXIBLE ARBEITSZEIT</p><h2>Flexibel für wen?</h2><div class="tension-grid"><div class="tension good"><span>FLEXIBILITÄTSMÖGLICHKEIT</span><h3>Ich kann beeinflussen, wann ich arbeite.</h3><p>Arbeitszeitsouveränität und Mitgestaltung durch Beschäftigte.</p></div><div class="tension risk"><span>FLEXIBILITÄTSANFORDERUNG</span><h3>Ich muss verfügbar sein, wenn Arbeit anfällt.</h3><p>Betriebliche Flexibilität kann Planbarkeit und Erholung beeinträchtigen.</p></div></div><p class="takeaway"><b>New Work ist nicht automatisch mehr Freiheit:</b> Entscheidend ist, wer Kontrolle über die Flexibilität hat.</p><div class="source-row mode-only-learning"><a href="https://www.baua.de/DE/Themen/Arbeitsgestaltung/Arbeitszeit/Flexible-Arbeitszeiten" target="_blank" rel="noopener">BAuA · Flexible Arbeitszeiten ↗</a></div></section>`},

 {id:"flex-europa",title:"Flexibles Arbeiten EU",html:`<section class="scene editorial-bg editorial-people"><div class="photo-split"><div><p class="eyebrow">EUROFOUND · REPORT 2026</p><h2>Flexibilität ist strukturell geworden – aber sie hat einen Preis.</h2><div class="big-number">mind. 1 von 5</div><p class="lead">Beschäftigten in der EU nutzte 2024 Telearbeit oder flexible Arbeitszeitregelungen.</p><div class="lecture-source">Quelle: Eurofound (2026), Daten u. a. aus EWCS 2024 / EU-LFS</div><div class="proscons"><div><b>+</b> bessere Work-Life-Balance, weniger Pendelzeit, teils weniger Erschöpfung</div><div><b>–</b> längere/irreguläre Zeiten, Arbeit in der Freizeit, ständige Erreichbarkeit</div></div><div class="source-row mode-only-learning"><a href="https://www.eurofound.europa.eu/en/publications/all/working-anytime-anywhere-in-the-EU-after-pandemic-effects-quality-working-time" target="_blank" rel="noopener">Eurofound · Working anytime, anywhere, 2026 ↗</a></div></div><div class="photo-panel"><img src="https://images.pexels.com/photos/4050315/pexels-photo-4050315.jpeg?auto=compress&cs=tinysrgb&w=1200" alt="Person arbeitet flexibel von zuhause"><div class="photo-caption">Autonomie und Entgrenzung können gleichzeitig auftreten.</div></div></div></section>`},

 {id:"global",title:"Globaler Blick",html:`<section class="scene"><p class="eyebrow">INTERNATIONALER BLICK · ILO</p><h2>Arbeitszeit ist global sehr ungleich verteilt.</h2><div class="stat-grid"><div class="stat-card"><b>&gt; ⅓</b><span>arbeiten regelmäßig<br><b>mehr als 48 h/Woche</b></span></div><div class="stat-card"><b>≈ ⅕</b><span>arbeiten kurze Arbeitszeiten<br><b>unter 35 h/Woche</b></span></div><div class="stat-card accent"><b>Mismatch</b><span>Mehr Stunden als gewünscht hängt mit schlechterer berichteter Work-Life-Balance zusammen.</span></div></div><div class="coverage-box"><b>Datenbasis der Arbeitszeitverteilung:</b> nationale Haushalts-/Arbeitskräfteerhebungen aus <b>160 Ländern</b>, entsprechend rund <b>95 % der weltweiten Beschäftigung</b> (2019 bzw. letztes verfügbares Jahr). Abgedeckte Regionen: Afrika, Amerika, Arabische Staaten, Asien/Pazifik sowie Europa/Zentralasien.</div><p class="micro">Beispiel für die Spannweite der durchschnittlichen Wochenarbeitszeit: Südliches Asien 49,0 h · Ostasien 48,8 h · Nordamerika 37,9 h · Nord-/Süd-/Westeuropa 37,2 h. Die ILO-Zahlen sind deshalb ein globaler Strukturvergleich und kein „2026-Weltwert“.</p><div class="lecture-source">Quelle: ILO, Working Time and Work-Life Balance Around the World, 2022/2023, Kap. 2</div><div class="source-row mode-only-learning"><a href="https://www.ilo.org/publications/working-time-and-work-life-balance-around-world" target="_blank" rel="noopener">ILO · Working Time and Work-Life Balance Around the World ↗</a></div></section>`},

 {id:"vier-tage",title:"4-Tage-Woche · Deutschland",html:`<section class="scene"><div class="photo-split"><div><p class="eyebrow">4-TAGE-WOCHE · DEUTSCHLAND</p><h2>Weniger Zeit – aber nicht einfach „Freitag frei“.</h2><div class="formula"><b>100</b><span>% Leistung</span><b>80</b><span>% Zeit</span><b>100</b><span>% Lohn</span></div><p class="lead">Im deutschen Pilotprojekt 2024 wurden 45 Organisationen gestartet; 41 führten das Modell vollständig ein bzw. fort.</p><p class="micro">Die Unternehmen unterschieden sich stark in Branche, Größe und konkreter Umsetzung. Das ist ein Pilot – keine repräsentative Stichprobe der deutschen Wirtschaft.</p><div class="source-row mode-only-learning"><a href="https://www.uni-muenster.de/news/view.php?cmdid=14337" target="_blank" rel="noopener">Universität Münster · Ergebnisse 2024 ↗</a></div></div><div class="photo-panel"><img src="https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&w=1200" alt="Team im Büro"><div class="photo-caption">Arbeitszeitreduktion verlangt Prozessveränderung.</div></div></div></section>`},

 {id:"vier-tage-followup",title:"4-Tage-Woche · Follow-up 2026",html:`<section class="scene"><p class="eyebrow">FOLLOW-UP · DEUTSCHLAND · 2026</p><h2>Was blieb zwei Jahre später?</h2><div class="follow-grid"><div><b>70 %</b><span>der 40 Follow-up-Organisationen arbeiteten weiterhin mit einer Form der Arbeitszeitreduktion</span></div><div><b>94 %</b><span>der weiterführenden Organisationen berichteten bessere Work-Life-Balance</span></div><div><b>74 %</b><span>berichteten verbesserte Innovation & Kreativität</span></div><div><b>74 %</b><span>berichteten höhere Arbeitgeberattraktivität</span></div></div><p class="micro"><b>Achtung:</b> Diese Prozentwerte beziehen sich auf die Organisationen, die die Arbeitszeitreduktion fortführten – nicht auf alle deutschen Unternehmen. Es handelt sich um berichtete Organisationseffekte.</p><div class="source-row mode-only-learning"><a href="https://www.wiwi.uni-muenster.de/fakultaet/de/news/5465" target="_blank" rel="noopener">Universität Münster · Follow-up 2026 ↗</a><a href="https://www.wiwi.uni-muenster.de/tow/sites/tow/files/downloads/4DW_FollowUp_Report_Deutsch.pdf" target="_blank" rel="noopener">Follow-up-Bericht PDF ↗</a></div></section>`},

 {id:"vier-tage-international",title:"4-Tage-Woche · international",html:`<section class="scene"><div class="photo-split"><div><p class="eyebrow">INTERNATIONALE EVIDENZ</p><h2>Die Evidenz wird breiter – aber Kausalität und Auswahl bleiben wichtig.</h2><div class="big-number">2.896</div><p class="lead">Beschäftigte aus <b>141 Organisationen</b> in einem internationalen 6-Monats-4-Tage-Woche-Versuch.</p><p>Eine 2025 berichtete internationale Studie fand Verbesserungen bei körperlicher und mentaler Gesundheit, Work-Life-Balance und Burnout nach Arbeitszeitreduktion.</p><p class="micro">Auch hier gilt: teilnehmende Organisationen wählen sich in solche Programme hinein. Das begrenzt die Übertragbarkeit.</p><div class="source-row mode-only-learning"><a href="https://www.nature.com/articles/s41562-025-02262-x" target="_blank" rel="noopener">Nature Human Behaviour · 2025 ↗</a></div></div><div class="photo-panel"><img src="https://images.pexels.com/photos/3184339/pexels-photo-3184339.jpeg?auto=compress&cs=tinysrgb&w=1200" alt="Internationales Team"><div class="photo-caption">Internationaler Blick auf Arbeitszeitreduktion.</div></div></div></section>`},

 {id:"arbeitszeit-modelle",title:"Arbeitszeitmodelle",html:`<section class="scene editorial-bg editorial-people"><p class="eyebrow">GESTALTUNGSOPTIONEN</p><h2>Es gibt nicht „das“ flexible Arbeitszeitmodell.</h2><div class="model-grid"><div><b>GLEITZEIT</b><span>Beginn/Ende innerhalb eines Rahmens variieren</span></div><div><b>VERTRAUENSARBEITSZEIT</b><span>mehr Eigensteuerung – aber nicht ohne Arbeitszeiterfassung</span></div><div><b>TEILZEIT</b><span>vertraglich reduzierte Arbeitszeit</span></div><div><b>JOBSHARING</b><span>zwei oder mehr Personen teilen Verantwortung/Stelle</span></div><div><b>4-TAGE-WOCHE</b><span>kann Verdichtung oder echte Reduktion bedeuten</span></div><div><b>SCHICHTMODELLE</b><span>Flexibilität muss auch jenseits von Wissensarbeit gestaltet werden</span></div></div><div class="workshop-brief"><b>Mini-Transfer · 3er-Gruppen · 6 Minuten</b><span>Wählen Sie <b>zwei</b> Modelle. Vergleichen Sie sie für eine Organisation Ihrer Wahl anhand von: (1) Problem, das gelöst werden soll, (2) Nutzen für Beschäftigte, (3) Nutzen für Arbeitgeber, (4) größtes Risiko, (5) eine notwendige Regel.</span><em>Output: eine Empfehlung in genau 3 Sätzen. Zwei Gruppen präsentieren je 60 Sekunden.</em></div></section>`},

 {id:"arbeitszeit-case",title:"Managemententscheidung",html:`<section class="scene editorial-bg editorial-meeting"><p class="eyebrow">MANAGEMENT CASE · 8 MIN</p><h2>Sie entscheiden über die Arbeitszeit.</h2><div class="casebox"><p><b>Die NovaWorks GmbH</b> hat 850 Beschäftigte weltweit in Entwicklung, Kundenservice und Produktion. Fluktuation steigt, Bewerbungen sinken. Beschäftigte wünschen mehr Flexibilität. Führungskräfte fürchten Erreichbarkeits- und Produktivitätsprobleme.</p></div><div class="choice-grid"><button class="work-choice">A · Gleitzeit + Kernzeit</button><button class="work-choice">B · Vertrauensarbeitszeit</button><button class="work-choice">C · 4-Tage-Pilot</button><button class="work-choice">D · Team-spezifische Modelle</button></div><div class="case-task"><b>Management-Challenge · 4er-Gruppen · 12 Minuten</b><span><b>Entscheiden:</b> A, B, C oder D – und begründen Sie die Wahl für Entwicklung, Kundenservice und Produktion. <b>Gestalten:</b> Legen Sie 2 verbindliche Spielregeln fest. <b>Messen:</b> Bestimmen Sie 2 Kennzahlen, an denen Sie nach 6 Monaten Erfolg oder Misserfolg erkennen. <b>Abwägen:</b> Benennen Sie einen Nachteil/Zielkonflikt, den Sie bewusst akzeptieren.</span><em><b>Pitch:</b> 90 Sekunden pro Gruppe: Entscheidung → Begründung → Regeln → KPIs → Trade-off. Danach stimmt der Kurs über die überzeugendste Lösung ab.</em></div></section>`},

 {id:"arbeitszeit-fazit",title:"Arbeitszeit · Fazit",html:`<section class="scene editorial-bg editorial-people"><p class="eyebrow">KAPITEL 2 · TAKE-AWAY</p><h2>Gute Arbeitszeitgestaltung optimiert nicht nur Stunden.</h2><div class="summary-words"><span>Autonomie</span><span>Planbarkeit</span><span>Gesundheit</span><span>Produktivität</span><span>Fairness</span></div><blockquote>Die entscheidende Frage lautet nicht: „Welches Modell ist modern?“<br><b>Sondern: Welches Modell passt zu Arbeit, Menschen und Organisation – und zu welchem Preis?</b></blockquote><button class="cta" data-next>Weiter →</button></section>`}
];

