// v4.4: Arrange Block 1 in six coherent chapters, 3 per day.
const b1Start=scenes.findIndex(x=>x.id==="home");
const b1End=scenes.findIndex(x=>x.id==="b2-start");
if(b1Start>=0){
 const firstBlock=scenes.splice(b1Start); // all block 1 slides; block 2 added below
 const byId=new Map(firstBlock.map(x=>[x.id,x]));
 const moved=new Set();
 const add=(arr,ids)=>ids.forEach(id=>{if(byId.has(id)&&!moved.has(id)){arr.push(byId.get(id));moved.add(id)}});
 const take=(a,b)=>{const ai=firstBlock.findIndex(x=>x.id===a),bi=firstBlock.findIndex(x=>x.id===b);return ai>=0&&bi>=ai?firstBlock.slice(ai,bi+1).map(x=>x.id):[]};
 const ordered=[];
 add(ordered,take("home","c1-est-5"));
 add(ordered,["kahoot-k1"]);
 add(ordered,take("arbeitszeit-start","c2-est-5"));
 add(ordered,["kahoot-k2"]);
 add(ordered,take("c3-start","c3-end").filter(id=>id!=="c3-end"));
 add(ordered,["wp-reasons","wp-numbers","wp-design-options","wp-evidence2","wp-cost","wp-data"]);
 add(ordered,["day1-workplace","day1-workplace-review","c3-end"]);
 add(ordered,take("c4-start","c4-end"));
 add(ordered,["day1-bayer","day1-transfer","day1-cliff","kahoot-k3"]);
 add(ordered,["day2-robotics","robot-now","robot-limits","robot-bmw-us","robot-bmw-de","robot-ifr","robot-physical-ai","robot-future","robot-work","robot-decision","day2-cobot-task"]);
 add(ordered,take("c5-start","c5-end"));
 add(ordered,["day2-ai-status","day2-ai-use","day2-ai-jobs","day2-ai-skills","day2-ai-career","day2-ai-economy","day2-video","day2-ailit","day2-ki-evidence","day2-mission-review","kahoot-k4"]);
 add(ordered,take("c6-start","c6-end"));
 add(ordered,["kahoot-k5"]);
 add(ordered,take("finale-start","finale-end"));
 add(ordered,["day2-system","day2-blueprint","day2-blueprint-template","day2-pitches","day2-redteam","day2-exit","kahoot-k6"]);
 firstBlock.forEach(x=>{if(!moved.has(x.id))ordered.push(x)});
 scenes.push(...ordered);
}


/* === v3.0 · BLOCK 1 BEREINIGUNG + BLOCK 2 DIGITAL ORGANIZATION === */
const block2Scenes=[
{"id":'b2-start',"title":'Digital Organization',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · NEUER BLICKWINKEL</div><h1>Digital Organization</h1><div class="b2-layout"><div><p class="lead">Block 1 fragte: <strong>Wie gestalten wir Arbeit?</strong><br>Block 2 fragt: <strong>Wie gestalten wir Organisation, Kundennutzen und digitale Wertschöpfung?</strong></p>\n<div class="chapter-map"><b>01 Purpose</b><b>02 Organisation</b><b>03 Transformation</b><b>04 Customer Centricity</b><b>05 Design</b><b>06 Digitale Wertschöpfung</b></div>\n<p class="callout">Die Inhalte dieses Blocks basieren eng auf dem Skript von Christoph Witt / Claudia Schwabe. NovaWorks verbindet die Themen als durchgehendes Planspiel.</p></div></div></section>'},
{"id":'b2c1-start',"title":'Purpose Driven Organization',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · KAPITEL 1</div><h1>Purpose Driven Organization</h1><div class="b2-layout"><div><p class="lead">Sinn und Zweck der Organisation als Grundlage für Zusammenarbeit.</p>\n<div class="triad"><b>PARTIZIPATION</b><b>SELBSTORGANISATION</b><b>AGILITÄT</b></div></div><figure class="b2-visual"><img src="assets/block2/purpose.jpg" alt="Purpose Driven Organization"><figcaption>Visual aus dem Originalskript Witt/Schwabe · WS24/25</figcaption></figure></div></section>'},
{"id":'b2c1-purpose',"title":'Purpose = Sinn + Zweck',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 1 · GRUNDIDEE</div><h1>Purpose = Sinn + Zweck</h1><div class="b2-layout"><div><p><strong>Emotional:</strong> Sinn und Sinnerfüllung. <strong>Rational:</strong> Orientierung und Navigation.</p>\n<p>Vom <strong>Warum</strong> werden Strukturen und Prozesse abgeleitet; erst danach Produkte und Dienstleistungen.</p></div></div></section>'},
{"id":'b2c1-golden',"title":'The Golden Circle',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 1 · WHY → HOW → WHAT</div><h1>The Golden Circle</h1><div class="b2-layout"><div><div class="three-cols"><div><strong>WHY</strong><p>Warum gibt es uns? Werte, Überzeugungen, Antrieb.</p></div><div><strong>HOW</strong><p>Wie unterscheiden wir uns? Welches Versprechen geben wir?</p></div><div><strong>WHAT</strong><p>Welche Produkte und Services bieten wir?</p></div></div></div></div></section>'},
{"id":'b2c1-five',"title":'Die fünf Disziplinen',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 1 · FINK / MOELLER</div><h1>Die fünf Disziplinen</h1><div class="b2-layout"><div><div class="stack-cards"><b>Sinn als Steuerungsinstrument</b><b>Agile Aufbauorganisation</b><b>Partnerschaftliche Personalsysteme</b><b>Hochflexible Organisationskultur</b><b>Co-Evolution im Business-Ökosystem</b></div></div></div></section>'},
{"id":'b2c1-drive',"title":'Autonomy · Mastery · Purpose',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 1 · MOTIVATION</div><h1>Autonomy · Mastery · Purpose</h1><div class="b2-layout"><div><p class="lead">Das Originalskript verbindet Purpose mit Daniel Pinks drei Elementen intrinsischer Motivation.</p>\n<div class="triad"><b>AUTONOMY<br><small>Selbstbestimmung</small></b><b>MASTERY<br><small>Weiterentwicklung</small></b><b>PURPOSE<br><small>Sinnerfüllung</small></b></div></div></div></section>'},
{"id":'b2c1-challenge',"title":'Challenge · Purpose unter Druck',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 1 · 8 MIN</div><h1>Challenge · Purpose unter Druck</h1><div class="b2-layout"><div><p><strong>NovaWorks behauptet:</strong> „Wir machen Arbeit digitaler.“ Reicht das als Purpose?</p>\n<ol><li>Formuliert ein WHY in einem Satz.</li><li>Leitet zwei HOW-Prinzipien ab.</li><li>Prüft: Welche bisherige NovaWorks-Entscheidung würde sich dadurch ändern?</li></ol>\n<div class="challenge-output">OUTPUT · WHY + 2 HOWs + 1 Konsequenz</div></div></div></section>'},
{"id":'b2c1-nova',"title":'Mission 08 · Purpose Compass',"html":'<section class="scene-inner b2-scene mission"><div class="eyebrow">NOVAWORKS</div><h1>Mission 08 · Purpose Compass</h1><div class="b2-layout"><div><p>Entwickelt für NovaWorks einen Purpose Compass: <strong>WHY → Prinzipien → beobachtbares Verhalten → No-Gos</strong>.</p>\n<p>Der Purpose darf nicht nur gut klingen: Er muss eine echte Entscheidung ermöglichen.</p></div></div></section>'},
{"id":'b2c1-end',"title":'Purpose ist kein Poster',"html":'<section class="scene-inner b2-scene dark"><div class="eyebrow">KAPITEL 1 · TAKE-AWAY</div><h1>Purpose ist kein Poster</h1><div class="b2-layout"><div><p class="lead">Purpose wird erst dann zur Organisationslogik, wenn er Entscheidungen, Strukturen und Verhalten beeinflusst.</p></div></div></section>'},
{"id":'b2c2-start',"title":'Von der klassischen zur adaptiven Organisation',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · KAPITEL 2</div><h1>Von der klassischen zur adaptiven Organisation</h1><div class="b2-layout"><div><p class="lead">Wie verändert sich Organisation, wenn Komplexität und Veränderung zunehmen?</p></div><figure class="b2-visual"><img src="assets/block2/org_evolution.png" alt="Evolution der Organisationsformen"><figcaption>Visual aus dem Originalskript Witt/Schwabe · WS24/25</figcaption></figure></div></section>'},
{"id":'b2c2-mintzberg',"title":'Mintzberg als Ausgangspunkt',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 2 · ORGANISATION</div><h1>Mintzberg als Ausgangspunkt</h1><div class="b2-layout"><div><p>Das Originalskript nutzt Mintzbergs Konfiguration, um formale Organisation sichtbar zu machen – und stellt ihr die reale Mitbestimmung und informelle Organisation gegenüber.</p>\n<div class="callout">Organigramm ≠ tatsächlicher Entscheidungsfluss.</div></div></div></section>'},
{"id":'b2c2-cvf',"title":'Competing Values Framework',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 2 · KULTUR</div><h1>Competing Values Framework</h1><div class="b2-layout"><div><p>Zwei Spannungsachsen strukturieren Organisationskulturen: <strong>intern ↔ extern</strong> und <strong>Kontrolle ↔ Flexibilität</strong>.</p>\n<p>Die Kernfrage lautet nicht „Welche Form ist modern?“, sondern: <strong>Welche Logik passt zu Kontext und Aufgabe?</strong></p></div></div></section>'},
{"id":'b2c2-pods',"title":'Podularity',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 2 · AUTARKE TEAMS</div><h1>Podularity</h1><div class="b2-layout"><div><p>Geteilte Verantwortung durch weitgehend autarke Teamstrukturen. Kreative Verbindungen ersetzen detaillierte Prozessketten – aber gemeinsame Standards bleiben nötig.</p></div><figure class="b2-visual"><img src="assets/block2/podularity.jpg" alt="Podularity im Originalskript"><figcaption>Visual aus dem Originalskript Witt/Schwabe · WS24/25</figcaption></figure></div></section>'},
{"id":'b2c2-adhocracy',"title":'Adhocracy & Holacracy',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 2 · ALTERNATIVE FORMEN</div><h1>Adhocracy & Holacracy</h1><div class="b2-layout"><div><p><strong>Adhocracy:</strong> Experten verschiedener Bereiche bilden dynamische Teams für konkrete Aufgaben.</p>\n<p><strong>Holacracy:</strong> Rollen und Kreise verteilen Autorität anders als klassische Stellenhierarchien.</p></div></div></section>'},
{"id":'b2c2-common',"title":'Was innovative Organisationsformen verbindet',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 2 · ZUSAMMENFASSUNG</div><h1>Was innovative Organisationsformen verbindet</h1><div class="b2-layout"><div><div class="stack-cards"><b>Organisation als lebendes System</b><b>weniger starre Hierarchie</b><b>Verantwortung im Team / Pod / Kreis</b><b>Impulse zentral – Entwicklung stärker bottom-up</b></div></div></div></section>'},
{"id":'b2c2-challenge',"title":'Challenge · Wer entscheidet?',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 2 · 10 MIN</div><h1>Challenge · Wer entscheidet?</h1><div class="b2-layout"><div><p>Ordnet sechs NovaWorks-Entscheidungen einer Struktur zu: <strong>Linie · cross-funktionales Team · Pod · temporäre Adhocracy</strong>.</p>\n<p>Begründet für zwei Entscheidungen, warum die Alternative schlechter wäre.</p></div></div></section>'},
{"id":'b2c2-nova',"title":'Mission 09 · Organization Fit',"html":'<section class="scene-inner b2-scene mission"><div class="eyebrow">NOVAWORKS</div><h1>Mission 09 · Organization Fit</h1><div class="b2-layout"><div><p>Entwerft eine Organisationsarchitektur für NovaWorks. Nicht alles muss agil sein.</p>\n<p><strong>Pflicht:</strong> 3 Organisationseinheiten · Entscheidungslogik · 2 Schnittstellenstandards · 1 bewusst hierarchischer Bereich.</p></div></div></section>'},
{"id":'b2c3-start',"title":'Digitale Transformation & Organisation',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · KAPITEL 3</div><h1>Digitale Transformation & Organisation</h1><div class="b2-layout"><div><p class="lead">Digitalisierung verändert nicht nur Werkzeuge – sondern Prozesse, Kundenerlebnis und Geschäftsmodelle.</p></div></div></section>'},
{"id":'b2c3-disruption',"title":'Disruption verändert Marktspielregeln',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 3 · DISRUPTION</div><h1>Disruption verändert Marktspielregeln</h1><div class="b2-layout"><div><p>Das Skript beschreibt Disruption als Veränderung bestehender Marktspielregeln durch Innovation und neue Geschäftsmodelle.</p>\n<div class="challenge-output">DENKFRAGE · Wann ist etwas nur digitalisiert – und wann transformiert es das Geschäft?</div></div></div></section>'},
{"id":'b2c3-it',"title":'Kein Business ohne IT',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 3 · IT-ORGANISATION</div><h1>Kein Business ohne IT</h1><div class="b2-layout"><div><p>IT wird im Originalskript als zentraler Treiber unternehmerischer Wertschöpfung beschrieben: interdisziplinäre Teams, Netzwerke, agile und endnutzerzentrierte Entwicklung, flexible Architekturen und Security als Querschnitt.</p></div></div></section>'},
{"id":'b2c3-roles',"title":'Neue digitale Rollen',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 3 · ROLLEN</div><h1>Neue digitale Rollen</h1><div class="b2-layout"><div><div class="four-cols"><b>Chief Digital Officer</b><b>Chief Product Owner</b><b>Community Manager</b><b>Social Media Manager</b></div>\n<p>Die Rollen sind Ausdruck neuer Aufgaben – nicht automatisch die Lösung für Transformation.</p></div></div></section>'},
{"id":'b2c3-challenge',"title":'Challenge · Digitalisierung oder Transformation?',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 3 · 7 MIN</div><h1>Challenge · Digitalisierung oder Transformation?</h1><div class="b2-layout"><div><p>Klassifiziert fünf Veränderungen bei NovaWorks: <strong>Digitisierung · Digitalisierung · Transformation</strong>.</p>\n<p>Wählt anschließend genau eine Maßnahme, die das Geschäftsmodell oder Kundenerlebnis tatsächlich verändert.</p></div></div></section>'},
{"id":'b2c3-nova',"title":'Mission 10 · Transformation Map',"html":'<section class="scene-inner b2-scene mission"><div class="eyebrow">NOVAWORKS</div><h1>Mission 10 · Transformation Map</h1><div class="b2-layout"><div><p>Erstellt eine Map aus <strong>Technologie → Prozess → Kundennutzen → Geschäftsmodell</strong>.</p>\n<p>Markiert eine Abhängigkeit, ein Risiko und eine Fähigkeit, die NovaWorks neu aufbauen muss.</p></div></div></section>'},
{"id":'b2c4-start',"title":'Customer Centricity & Customer Journey',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · KAPITEL 4</div><h1>Customer Centricity & Customer Journey</h1><div class="b2-layout"><div><p class="lead">Vom internen Geschäftsprozess zum Kundenprozess.</p></div></div></section>'},
{"id":'b2c4-process',"title":'Paradigmenwechsel',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 4 · OPERATIONAL EXCELLENCE</div><h1>Paradigmenwechsel</h1><div class="b2-layout"><div><div class="compare"><div><small>FRÜHER</small><h3>Geschäftsprozess</h3><p>interne Effizienz der Leistungserstellung</p></div><div><small>JETZT</small><h3>Kundenprozess</h3><p>Customer Journey, Beziehung und Nutzungserlebnis</p></div></div></div></div></section>'},
{"id":'b2c4-logic',"title":'Value-in-Exchange → Value-in-Use',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 4 · SERVICE-DOMINIERTE LOGIK</div><h1>Value-in-Exchange → Value-in-Use</h1><div class="b2-layout"><div><p><strong>Güter-dominierte Logik:</strong> Wert wird im Produkt gebunden und beim Kauf übertragen.</p>\n<p><strong>Service-dominierte Logik:</strong> Wert entsteht in der Nutzung und gemeinsam mit dem Kunden.</p>\n<div class="callout">Nicht: „Wir stellen Laufschuhe her.“ → Sondern: „Wir erleichtern dir, regelmäßig Sport zu machen.“</div></div></div></section>'},
{"id":'b2c4-journey',"title":'Customer Journey',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 4 · REISE DES KUNDEN</div><h1>Customer Journey</h1><div class="b2-layout"><div><p>Die Customer Journey betrachtet die Erfahrung über Kontaktpunkte hinweg – nicht nur einzelne interne Prozessschritte.</p>\n<div class="journey"><b>BEDARF</b><span>→</span><b>INFORMATION</b><span>→</span><b>NUTZUNG</b><span>→</span><b>SERVICE</b><span>→</span><b>BINDUNG</b></div></div></div></section>'},
{"id":'b2c4-persona',"title":'Know your Customer',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 4 · PERSONAS</div><h1>Know your Customer</h1><div class="b2-layout"><div><p>Das Originalskript nennt u. a. Personas als Werkzeug, um Kundenbedürfnisse und Nutzungskontexte greifbarer zu machen.</p>\n<p class="callout">Persona ≠ dekorative Zielgruppenbeschreibung. Sie soll Designentscheidungen verbessern.</p></div></div></section>'},
{"id":'b2c4-challenge',"title":'Challenge · Journey Breakdown',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 4 · 12 MIN</div><h1>Challenge · Journey Breakdown</h1><div class="b2-layout"><div><p>Wählt eine NovaWorks-Leistung. Zeichnet fünf Schritte der Customer Journey und markiert:</p>\n<ul><li>größten Pain Point</li><li>Moment of Truth</li><li>digitale Chance</li><li>Messgröße für Kundennutzen</li></ul></div></div></section>'},
{"id":'b2c4-nova',"title":'Mission 11 · Customer Journey Redesign',"html":'<section class="scene-inner b2-scene mission"><div class="eyebrow">NOVAWORKS</div><h1>Mission 11 · Customer Journey Redesign</h1><div class="b2-layout"><div><p>Redesignt eine NovaWorks-Journey vom Kundenproblem aus – nicht vom bestehenden Prozess.</p>\n<p><strong>Output:</strong> Journey + Pain Point + neues Wertversprechen + 2 Experience-KPIs.</p></div></div></section>'},
{"id":'b2c5-start',"title":'Customer-Centric Design',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · KAPITEL 5</div><h1>Customer-Centric Design</h1><div class="b2-layout"><div><p class="lead">Probleme identifizieren, Lösungen verproben, Kunden früh einbeziehen.</p>\n<div class="triad"><b>DESIGN THINKING</b><b>SERVICE DESIGN</b><b>CROWD DESIGN</b></div></div></div></section>'},
{"id":'b2c5-problem',"title":'Problem vor Lösung',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 5 · EXPLORATION</div><h1>Problem vor Lösung</h1><div class="b2-layout"><div><p>Das Skript betont: In der Exploration wird nicht gefragt „Wollt ihr diese Lösung?“, sondern <strong>Was braucht ihr – und warum?</strong></p>\n<div class="callout">Kundenerlebnis zuerst denken, Technologie danach.</div></div></div></section>'},
{"id":'b2c5-loop',"title":'Iterativ statt einmalig',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 5 · VORGEHEN</div><h1>Iterativ statt einmalig</h1><div class="b2-layout"><div><div class="journey"><b>VERSTEHEN</b><span>→</span><b>IDEEN</b><span>→</span><b>PROTOTYP</b><span>→</span><b>TEST</b><span>↺</span></div>\n<p>Das Originalskript stellt Prototypen-, Risiko-, inkrementelle und iterative Modelle gegenüber.</p></div></div></section>'},
{"id":'b2c5-challenge',"title":'Challenge · Die falsche Lösung',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 5 · 10 MIN</div><h1>Challenge · Die falsche Lösung</h1><div class="b2-layout"><div><p>Ihr bekommt eine bereits beschlossene NovaWorks-Lösung. Eure Aufgabe: <strong>verbietet euch die Lösung für zehn Minuten.</strong></p>\n<p>Formuliert stattdessen 5 Problemfragen und 3 Beobachtungen, die ihr bei Kunden erheben müsstet.</p></div></div></section>'},
{"id":'b2c5-prototype',"title":'Prototype before PowerPoint',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 5 · 15 MIN</div><h1>Prototype before PowerPoint</h1><div class="b2-layout"><div><p>Baut einen extrem einfachen Prototyp der neuen Journey oder des Services: Papier, Ablaufskizze oder klickbarer Low-Fidelity-Entwurf.</p>\n<div class="challenge-output">TESTFRAGE · Was wollen wir durch den Prototyp lernen?</div></div></div></section>'},
{"id":'b2c5-nova',"title":'Mission 12 · Customer-Centric Design Sprint',"html":'<section class="scene-inner b2-scene mission"><div class="eyebrow">NOVAWORKS</div><h1>Mission 12 · Customer-Centric Design Sprint</h1><div class="b2-layout"><div><p><strong>Problem → Insight → How might we → Idee → Prototyp → Testannahme.</strong></p>\n<p>Eine andere Gruppe übernimmt für fünf Minuten die Rolle der Kunden und versucht, euren Prototyp scheitern zu lassen.</p></div></div></section>'},
{"id":'b2c6-start',"title":'Digitale Produkte, Services & Geschäftsmodelle',"html":'<section class="scene-inner b2-scene chapter-cover"><div class="eyebrow">BLOCK 2 · KAPITEL 6</div><h1>Digitale Produkte, Services & Geschäftsmodelle</h1><div class="b2-layout"><div><p class="lead">Von Produkten zu Services, von linearer Wertschöpfung zu digitalen Plattform- und Service-Logiken.</p></div><figure class="b2-visual"><img src="assets/block2/platform.png" alt="Plattformökonomie"><figcaption>Visual aus dem Originalskript Witt/Schwabe · WS24/25</figcaption></figure></div></section>'},
{"id":'b2c6-platform',"title":'Plattformökonomie',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 6 · GESCHÄFTSMODELLE</div><h1>Plattformökonomie</h1><div class="b2-layout"><div><p>Das Originalskript illustriert, wie digitale Geschäftsmodelle Wertschöpfung verschieben: Vermittlung, Netzwerke und Daten werden zu zentralen Ressourcen.</p>\n<div class="challenge-output">FRAGE · Was besitzt die Plattform – und was kontrolliert sie trotzdem?</div></div><figure class="b2-visual"><img src="assets/block2/platform.png" alt="Digitale Geschäftsmodelle"><figcaption>Visual aus dem Originalskript Witt/Schwabe · WS24/25</figcaption></figure></div></section>'},
{"id":'b2c6-serv',"title":'Servitization',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 6 · PRODUKT → SERVICE</div><h1>Servitization</h1><div class="b2-layout"><div><p><strong>Früher:</strong> Welche Produkte bieten wir an?<br><strong>Heute:</strong> Welche Services und Benefits stellen wir Kunden bereit?</p>\n<p>Servitization kombiniert Waren, Dienstleistungen, Support, Self-Services und Wissen zu einem erweiterten Nutzenangebot.</p></div></div></section>'},
{"id":'b2c6-product',"title":'Strategisches Produktmanagement',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 6 · PRODUKTMANAGEMENT</div><h1>Strategisches Produktmanagement</h1><div class="b2-layout"><div><p>Markt- und Branchenrecherche · Trendanalyse · Markt- und Produktstrategie · Produktdesign/-spezifikation · Entwicklung und Releaseplanung · Lifecycle Management.</p></div></div></section>'},
{"id":'b2c6-trends',"title":'Exogene & endogene Trends',"html":'<section class="scene-inner b2-scene "><div class="eyebrow">KAPITEL 6 · RADAR</div><h1>Exogene & endogene Trends</h1><div class="b2-layout"><div><div class="compare"><div><h3>EXOGEN</h3><p>Markt, Technologie, Kundenverhalten, Regulierung, Abhängigkeiten</p></div><div><h3>ENDOGEN</h3><p>Fähigkeiten, Prozesse, Organisation, Daten, Technologie</p></div></div>\n<p>Beides beeinflusst, welche digitalen Produkte und Services tragfähig sind.</p></div></div></section>'},
{"id":'b2c6-challenge',"title":'Challenge · Product Opportunity',"html":'<section class="scene-inner b2-scene challenge"><div class="eyebrow">KAPITEL 6 · 12 MIN</div><h1>Challenge · Product Opportunity</h1><div class="b2-layout"><div><p>Entwickelt drei digitale Produkt-/Service-Ideen für NovaWorks. Bewertet sie nach:</p>\n<div class="four-cols"><b>Kundennutzen</b><b>strategischer Fit</b><b>Machbarkeit</b><b>Geschäftspotenzial</b></div>\n<p>Nur eine Idee darf weiter.</p></div></div></section>'},
{"id":'b2c6-nova',"title":'Mission 13 · Digital Value Proposition',"html":'<section class="scene-inner b2-scene mission"><div class="eyebrow">NOVAWORKS</div><h1>Mission 13 · Digital Value Proposition</h1><div class="b2-layout"><div><p>Entwickelt das digitale Angebot von NovaWorks: <strong>Kundenproblem · Nutzenversprechen · Servicebestandteile · Erlös-/Wertlogik · Schlüsselressourcen · Risiken.</strong></p></div></div></section>'},
{"id":'b2-finale',"title":'Finale · NovaWorks Digital Organization 2030',"html":'<section class="scene-inner b2-scene dark"><div class="eyebrow">BLOCK 2 · FINALE</div><h1>Finale · NovaWorks Digital Organization 2030</h1><div class="b2-layout"><div><p class="lead">Verbindet beide Blöcke zu einem konsistenten Unternehmensdesign.</p>\n<div class="stack-cards"><b>Purpose & Prinzipien</b><b>Arbeitsgestaltung & Human–AI Workforce</b><b>Organisationsarchitektur</b><b>Customer Journey</b><b>Digitales Produkt / Service</b><b>KPIs, Risiken & Trade-offs</b></div>\n<div class="challenge-output">BOARDROOM PITCH · 4 Minuten + 2 Minuten kritische Fragen</div></div></div></section>'}
];
const removedBlock1Ids=new Set(scenes.filter(s=>s.id.startsWith("c6-")||s.id.startsWith("finale-")).map(s=>s.id));
for(let i=scenes.length-1;i>=0;i--){ if(removedBlock1Ids.has(scenes[i].id)) scenes.splice(i,1); }
scenes.push(...block2Scenes);
const block3Scenes=[{"id":"b3-start","title":"New Business Models","html":"<section class=\"scene-inner b3-scene chapter-cover\"><div class=\"eyebrow\">BLOCK 3 · PEOPLE, LEADERSHIP & CAREER</div><h1>New Business Models</h1><div class=\"b3-layout\"><div><p class=\"lead\">Was brauchen Organisationen jetzt von Menschen – und was bedeutet das für die eigene Karriere?</p><div class=\"chapter-map\"><b>01 SKILLS</b><b>02 GENERATIONEN</b><b>03 LEADERSHIP</b><b>04 FRAUEN & FÜHRUNG</b><b>05 CHANGE</b><b>06 YOUR FUTURE</b></div></div><figure class=\"b3-visual\"><img src=\"assets/block3/career_blueprint.svg\" alt=\"Vom Unternehmen zur eigenen Positionierung\"><figcaption>Vom Unternehmen zur eigenen Positionierung</figcaption></figure></div></section>"},{"id":"b3c1-start","title":"Skills statt Stellen","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1</div><h1>Skills statt Stellen</h1><div class=\"b3-layout\"><div><p class=\"lead\">Nicht nur die Frage „Welche Stelle besetzen wir?“, sondern: <strong>Welche Fähigkeiten brauchen wir, um unsere Strategie umzusetzen?</strong></p><div class=\"callout\">Lernziel: Kompetenzbedarfe erkennen, Lücken analysieren und geeignete Maßnahmen auswählen.</div></div><figure class=\"b3-visual\"><img src=\"assets/block3/skills_stack.svg\" alt=\"Illustration zum Thema Kompetenzen\"><figcaption>Kompetenzen sichtbar machen und gezielt entwickeln</figcaption></figure></div></section>"},{"id":"b3c1-est-1","title":"Schätzfrage 1: Veränderung der Kompetenzen","html":"<section class=\"scene estimate-scene\"><p class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · SCHÄTZFRAGE 1/5 · VERÄNDERUNG DER KOMPETENZEN</p><h2>Wie viel Prozent der heutigen Kernkompetenzen werden sich laut Arbeitgeberprognose bis 2030 verändern oder überholen?</h2><div class=\"estimate-options\"><span>19 %</span><span>29 %</span><span>39 %</span><span>59 %</span></div><button class=\"reveal-btn\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card\" hidden><div class=\"answer-big\">39 %</div><p>WEF, Future of Jobs Report 2025: Erwartete Veränderung von Kernkompetenzen zwischen 2025 und 2030. Das bedeutet nicht, dass 39 % aller Arbeitsplätze verschwinden.</p><div class=\"why\"><b>Diskussion:</b> Was bedeutet das für die Aktualität klassischer Stellenbeschreibungen?</div><a href=\"https://www.weforum.org/publications/the-future-of-jobs-report-2025/\" target=\"_blank\" rel=\"noopener\">Quelle und Methodik · 2025 ↗</a></div></section>"},{"id":"b3c1-est-2","title":"Schätzfrage 2: Weiterbildungsbedarf","html":"<section class=\"scene estimate-scene\"><p class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · SCHÄTZFRAGE 2/5 · WEITERBILDUNGSBEDARF</p><h2>Wie viele von 100 Beschäftigten benötigen laut WEF-Prognose bis 2030 eine Weiterbildung oder Umschulung?</h2><div class=\"estimate-options\"><span>41</span><span>49</span><span>59</span><span>79</span></div><button class=\"reveal-btn\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card\" hidden><div class=\"answer-big\">59 von 100</div><p>WEF, Future of Jobs Report 2025: Modellhafte globale Prognose. Darunter sind Weiterbildungen in bisherigen Rollen und Umschulungen für andere Tätigkeiten.</p><div class=\"why\"><b>Diskussion:</b> Wie müsste NovaWorks seine Personalentwicklung organisieren?</div><a href=\"https://www.weforum.org/publications/the-future-of-jobs-report-2025/\" target=\"_blank\" rel=\"noopener\">Quelle und Methodik · 2025 ↗</a></div></section>"},{"id":"b3c1-est-3","title":"Schätzfrage 3: Hindernis Transformation","html":"<section class=\"scene estimate-scene\"><p class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · SCHÄTZFRAGE 3/5 · HINDERNIS TRANSFORMATION</p><h2>Wie viel Prozent der befragten Arbeitgeber sehen Kompetenzlücken als wesentliches Hindernis für ihre Transformation?</h2><div class=\"estimate-options\"><span>33 %</span><span>48 %</span><span>63 %</span><span>85 %</span></div><button class=\"reveal-btn\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card\" hidden><div class=\"answer-big\">63 %</div><p>WEF, Future of Jobs Report 2025: Anteil der befragten Arbeitgeber, die Skill Gaps als wesentliches Transformationshindernis nennen.</p><div class=\"why\"><b>Diskussion:</b> Warum reicht es nicht, einfach neue Technologie einzukaufen?</div><a href=\"https://www.weforum.org/publications/the-future-of-jobs-report-2025/\" target=\"_blank\" rel=\"noopener\">Quelle und Methodik · 2025 ↗</a></div></section>"},{"id":"b3c1-est-4","title":"Schätzfrage 4: Strategie der Unternehmen","html":"<section class=\"scene estimate-scene\"><p class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · SCHÄTZFRAGE 4/5 · STRATEGIE DER UNTERNEHMEN</p><h2>Wie viel Prozent der befragten Arbeitgeber wollen die Weiterbildung ihrer Beschäftigten priorisieren?</h2><div class=\"estimate-options\"><span>50 %</span><span>63 %</span><span>70 %</span><span>85 %</span></div><button class=\"reveal-btn\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card\" hidden><div class=\"answer-big\">85 %</div><p>WEF, Future of Jobs Report 2025: Absichtserklärung befragter Unternehmen, keine gemessene Umsetzungsquote.</p><div class=\"why\"><b>Diskussion:</b> Wie kann ein Unternehmen prüfen, ob Weiterbildung wirklich Wirkung zeigt?</div><a href=\"https://www.weforum.org/publications/the-future-of-jobs-report-2025/\" target=\"_blank\" rel=\"noopener\">Quelle und Methodik · 2025 ↗</a></div></section>"},{"id":"b3c1-est-5","title":"Schätzfrage 5: Recruiting in Deutschland","html":"<section class=\"scene estimate-scene\"><p class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · SCHÄTZFRAGE 5/5 · RECRUITING IN DEUTSCHLAND</p><h2>Wie viel Prozent der befragten HR-Verantwortlichen in Deutschland berichten, dass weniger als die Hälfte der Bewerbungen die ausgeschriebenen Kriterien erfüllt?</h2><div class=\"estimate-options\"><span>37 %</span><span>52 %</span><span>67 %</span><span>77 %</span></div><button class=\"reveal-btn\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card\" hidden><div class=\"answer-big\">77 %</div><p>LinkedIn, März 2025: Befragung von Personalverantwortlichen in Deutschland. Es handelt sich um ihre Einschätzung der Bewerbungen, nicht um eine objektive Prüfung aller Bewerbungen.</p><div class=\"why\"><b>Diskussion:</b> Sollte NovaWorks Stellenanzeigen anders formulieren und Kompetenzen anders nachweisen lassen?</div><a href=\"https://www.mynewsdesk.com/de/linkedin-deutschland/pressreleases/mismatch-der-faehigkeiten-welche-skills-jetzt-auf-dem-deutschen-arbeitsmarkt-gefragt-sind-3375603\" target=\"_blank\" rel=\"noopener\">Quelle und Methodik · 2025 ↗</a></div></section>"},{"id":"b3c1-definition","title":"Was genau ist ein Skill?","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 1 · GRUNDLAGEN</div><h1>Was genau ist ein Skill?</h1><div class=\"b3-layout\"><div><p>Ein <strong>Skill</strong> ist eine erlernbare, in einer konkreten Aufgabe einsetzbare Fähigkeit. <strong>Kompetenz</strong> umfasst zusätzlich Wissen, Erfahrung, Haltung und situationsgerechtes Handeln.</p><div class=\"compare\"><div><h3>Beispiele für Skills</h3><p>Daten analysieren · Kundeninterviews führen · KI-Tools prüfen · Projekte moderieren</p></div><div><h3>Woran erkennt man sie?</h3><p>Arbeitsprobe · Projektergebnis · Simulation · nachvollziehbare Erfahrung</p></div></div><p class=\"callout\">Ein Zertifikat kann Wissen signalisieren. Ob jemand es anwenden kann, zeigt sich erst in der Praxis.</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/skills_stack.svg\" alt=\"Illustration zum Thema Kompetenzen\"><figcaption>Kompetenzen sichtbar machen und gezielt entwickeln</figcaption></figure></div></section>"},{"id":"b3c1-contrast","title":"Stellenorientiert vs. skillorientiert","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 1 · PERSPEKTIVWECHSEL</div><h1>Stellenorientiert vs. skillorientiert</h1><div class=\"b3-layout\"><div><div class=\"compare\"><div><h3>KLASSISCH</h3><p>Wir suchen eine Person für die Stelle „Digital Product Manager“ mit passendem Abschluss und fünf Jahren Erfahrung.</p></div><div><h3>SKILLORIENTIERT</h3><p>Wir brauchen Nutzerforschung, Priorisierung, Datenverständnis und Stakeholder-Kommunikation. Wer kann diese Aufgaben nachweislich übernehmen?</p></div></div><p><strong>Folge:</strong> Aufgaben können neu kombiniert, interne Talente gefunden und gezielter weitergebildet werden.</p><p class=\"callout\">Stellen und Verantwortung bleiben wichtig – Skills ergänzen die Organisations- und Personalplanung.</p></div></div></section>"},{"id":"b3c1-gap","title":"Warum Skill Gaps Transformation bremsen","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 1 · EVIDENZ</div><h1>Warum Skill Gaps Transformation bremsen</h1><div class=\"b3-layout\"><div><div class=\"big-stat\">63 %</div><p>der vom World Economic Forum befragten Arbeitgeber sehen <strong>fehlende Kompetenzen</strong> als wesentliche Hürde für die Transformation. Bis 2030 rechnen sie mit Veränderungen bei etwa <strong>39 %</strong> der heute benötigten Skills.</p><p><strong>Beispiel:</strong> NovaWorks führt KI-gestützten Kundenservice ein. Die Software ist verfügbar – aber niemand kann Antworten evaluieren, Datenqualität sichern oder Prozesse neu gestalten.</p><div class=\"callout\">Technologie kaufen ≠ Transformation umsetzen. Menschen müssen neue Arbeitsweisen beherrschen.</div><div class=\"source-note\">WEF Future of Jobs Report 2025 · globale Arbeitgeberbefragung · <a href=\"https://www.weforum.org/press/2025/01/future-of-jobs-report-2025-78-million-new-job-opportunities-by-2030-but-urgent-upskilling-needed-to-prepare-workforces/\" target=\"_blank\" rel=\"noopener\">Quelle</a></div></div></div></section>"},{"id":"b3c1-skillsbased","title":"Skills-based Hiring: Was ändert sich?","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 1 · RECRUITING</div><h1>Skills-based Hiring: Was ändert sich?</h1><div class=\"b3-layout\"><div><p><strong>Statt</strong> Bewerbende zuerst nach Studienabschluss oder bisherigem Jobtitel auszusortieren, prüft das Unternehmen konkrete Fähigkeiten und deren Nachweise.</p><ol><li>Erforderliche Skills aus Aufgaben ableiten.</li><li>Fähigkeiten mit strukturierten Interviews und Arbeitsproben prüfen.</li><li>Auch Quereinsteiger und interne Talente berücksichtigen.</li></ol><p>LinkedIn modelliert für einen skillorientierten Ansatz einen potenziell <strong>6,1-mal größeren Talentpool</strong> im globalen Durchschnitt. Das ist eine Modellrechnung, kein garantierter Recruiting-Erfolg.</p><div class=\"callout\">Abschlüsse bleiben für manche Berufe erforderlich oder besonders aussagekräftig.</div><div class=\"source-note\">LinkedIn Economic Graph · Skills-Based Hiring, März 2025 · <a href=\"https://economicgraph.linkedin.com/content/dam/me/economicgraph/en-us/PDF/skills-based-hiring-march-2025.pdf\" target=\"_blank\" rel=\"noopener\">Quelle</a></div></div><figure class=\"b3-visual\"><img src=\"assets/block3/skills_stack.svg\" alt=\"Illustration zum Thema Kompetenzen\"><figcaption>Kompetenzen sichtbar machen und gezielt entwickeln</figcaption></figure></div></section>"},{"id":"b3c1-hiring-praxis","title":"Skill-based Hiring in der Praxis","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 1 · PRAXIS-CHECK</div><h1>Skill-based Hiring: Realität oder Recruiting-Marketing?</h1><p class=\"lead\">Der Trend ist real – aber zwischen einer offenen Stellenanzeige und einer tatsächlich kompetenzbasierten Einstellung liegt ein großer Unterschied.</p><div class=\"b3-layout\"><div><h3>Was Unternehmen bereits tun</h3><ul><li><strong>IBM (USA):</strong> Öffnung vieler Stellen für Bewerbende ohne vierjährigen Hochschulabschluss; alternative Einstiegswege und praktische Eignungsprüfung.</li><li><strong>Accenture (Nordamerika):</strong> praxisorientierte Apprenticeship-Programme als alternative Einstiegswege.</li><li><strong>Deutsche Telekom:</strong> systematisches Skill Management und interne Kompetenzentwicklung – nicht gleichbedeutend mit Abschlussverzicht beim Recruiting.</li></ul><div class=\"callout\"><strong>Wichtige Unterscheidung:</strong> „Abschluss nicht erforderlich“ ≠ „Skills objektiv geprüft“ ≠ „mehr Personen ohne Abschluss eingestellt“.</div></div><div><h3>Was bleibt kritisch?</h3><ol><li>Welche Arbeitsproben oder Assessments messen relevante Fähigkeiten zuverlässig?</li><li>Welche Nachweise sind bei regulierten Berufen weiterhin notwendig?</li><li>Wie verhindert man neue Verzerrungen durch KI-gestütztes Matching?</li></ol><div class=\"callout\"><strong>Diskussion:</strong> KI-Projektmanagement: Masterabschluss mit wenig Praxis oder fünf Jahre belegbare Projekterfahrung ohne Studium? Welche <em>konkreten Nachweise</em> würdet ihr verlangen?</div></div></div><div class=\"source-note\">Quellen zur Vertiefung: <a href=\"https://www.hbs.edu/managing-the-future-of-work/Pages/default.aspx\" target=\"_blank\" rel=\"noopener\">Harvard Business School · Managing the Future of Work</a> · <a href=\"https://economicgraph.linkedin.com/\" target=\"_blank\" rel=\"noopener\">LinkedIn Economic Graph</a>. Beispiele beschreiben unterschiedliche Maßnahmen, keine einheitliche Erfolgsquote.</div></section>"},{"id":"b3c1-job-ads","title":"Zwei Stellenanzeigen im Vergleich","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 1 · REALER STELLENVERGLEICH</div><h1>Zwei ähnliche Jobs – zwei Wege zur Eignung</h1><p style=\"font-size:.92rem;margin:.35rem 0 .65rem\">Inhaltlich vollständige <b>deutsche Unterrichtsfassungen der veröffentlichten Anforderungen</b> (keine wörtlichen Originalanzeigen). Beide: Operations Analyst im Versicherungsumfeld.</p><div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;align-items:start;font-size:clamp(.67rem,.9vw,.9rem);line-height:1.3\"><div style=\"border:1px solid #cbd5e1;border-radius:12px;padding:.8rem;background:rgba(255,255,255,.94)\"><div style=\"font-weight:800;color:#1d4ed8;margin-bottom:.3rem\">A · QUALIFIKATIONSORIENTIERT</div><strong>STARR INSURANCE · Operations Analyst</strong><p><b>Aufgaben</b></p><ul><li>Operative Versicherungs- und Berichtsdaten erfassen, prüfen und aufbereiten.</li><li>Regulatorische Meldungen fristgerecht unterstützen und Abweichungen klären.</li><li>Daten mit Finance, Operations und weiteren Fachbereichen abstimmen.</li><li>Prozessdokumentation und Reporting verbessern.</li></ul><p><b>Erforderliches Profil</b></p><ul><li>Bachelor in BWL, Finance, Accounting, Versicherung, Data Analytics oder verwandtem Fach.</li><li>Ein bis zwei Jahre Erfahrung in Operations, Reporting oder Business Analysis.</li><li>Fortgeschrittenes Excel: Pivot-Tabellen, Formeln, Datenvalidierung.</li><li>Analytik, sorgfältiges Arbeiten, Organisation und Kommunikation.</li></ul><p><b>Von Vorteil</b></p><ul><li>Versicherungserfahrung, Compliance, Underwriting oder Datenmanagement.</li></ul></div><div style=\"border:1px solid #cbd5e1;border-radius:12px;padding:.8rem;background:rgba(255,255,255,.94)\"><div style=\"font-weight:800;color:#047857;margin-bottom:.3rem\">B · SKILLORIENTIERT</div><strong>AXA XL · Operations Analyst</strong><p><b>Geforderte Fähigkeiten</b></p><ul><li>Microsoft Office; Excel mit Formeln und Pivot-Tabellen.</li><li>Komplexe Daten und Statistiken mathematisch analysieren.</li><li>Professionelle Kommunikation und Stakeholdermanagement.</li><li>Eigenständig priorisieren, sorgfältig arbeiten, Veränderungen anstoßen.</li><li>Kreativ denken, bestehende Prozesse hinterfragen und Verbesserungen vorantreiben.</li><li>Motivation, sich im Versicherungsmarkt weiterzuentwickeln.</li></ul><p><b>Wünschenswerte Fähigkeiten</b></p><ul><li>Excel-Nachschlagefunktionen und WENN-Formeln.</li><li>Dateneingabe, Prozessarbeit und Projekterfahrung.</li><li>Erfahrung in Versicherungsadministration, London/Lloyd’s-Markt oder Underwriting.</li></ul><p><b>Formaler Abschluss</b></p><ul><li>Kein bestimmter Studienabschluss vorgeschrieben; einschlägige Erfahrung erwünscht, nicht zwingend.</li></ul></div></div><div class=\"callout\" style=\"margin-top:.55rem;font-size:.85rem\"><b>Diskussion (3 Minuten):</b> Welche fachlich geeigneten Quereinsteiger könnten bei A ausscheiden? Wie würdet ihr bei B die Skills praktisch überprüfen?</div><div class=\"source-note\" style=\"font-size:.7rem\">Quellen: Starr Insurance, Operations Analyst (Regulatory Reporting), 2026; OECD, <i>A Skills-First Labour Market</i> (2026), Tabelle 4.3, AXA XL (Stand 20.11.2025). Die Ausschreibungen unterscheiden sich in den konkreten Aufgaben.</div></section>"},{"id":"b3c1-map","title":"Wie entsteht eine Skill-Gap-Analyse?","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 1 · MANAGEMENTINSTRUMENT</div><h1>Wie entsteht eine Skill-Gap-Analyse?</h1><div class=\"b3-layout\"><div><p><strong>Schritt 1:</strong> Strategie und künftige Aufgaben festlegen. <strong>Schritt 2:</strong> Benötigte Skills definieren. <strong>Schritt 3:</strong> vorhandene Fähigkeiten anhand von Nachweisen erfassen. <strong>Schritt 4:</strong> Lücken priorisieren.</p><div class=\"compare\"><div><h3>NovaWorks benötigt</h3><p>KI-Qualitätssicherung: 4 Personen<br>Datenanalyse: 3 Personen<br>Kundeninterviews: 2 Personen</p></div><div><h3>Heute verfügbar</h3><p>KI-Qualitätssicherung: 1 Person<br>Datenanalyse: 2 Personen<br>Kundeninterviews: 2 Personen</p></div></div><p class=\"callout\">Ergebnis: Größte Lücke bei KI-Qualitätssicherung. Die Zahlen sind ein didaktisches Beispiel, keine Unternehmensdaten.</p></div></div></section>"},{"id":"b3c1-decision","title":"Fünf Wege, Kompetenzlücken zu schließen","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · STRATEGIE</div><h1>Fünf Strategien gegen Skill Gaps</h1><div class=\"b3-layout\"><div><p><strong>Die Botschaft:</strong> Fehlt eine Fähigkeit, ist Neueinstellung nur eine von fünf Lösungen. Die richtige Wahl hängt von <strong>Kosten, Zeit und Qualität</strong> ab.</p><div class=\"compare\"><div><h3>HIRE · Einstellen</h3><p>Neue Fachkraft für dauerhaft wichtige Skills.</p><h3>TRAIN · Qualifizieren</h3><p>Vorhandene Mitarbeitende gezielt weiterbilden.</p><h3>AI · Unterstützen</h3><p>Geeignete Routinetätigkeiten mit KI unterstützen – unter menschlicher Kontrolle.</p></div><div><h3>PARTNER · Extern vergeben</h3><p>Zeitlich begrenzt Spezialwissen einkaufen.</p><h3>STOP · Vereinfachen</h3><p>Optionale Funktionen streichen oder verschieben – keine Pflichtanforderungen.</p><p class=\"callout\"><strong>Leitfrage:</strong> Was ist innerhalb von zwölf Wochen zuverlässig und bezahlbar?</p></div></div></div></div></section>"},{"id":"b3c1-case","title":"NovaWorks: Team und Auftrag","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · NOVAWORKS · PLANSPIEL</div><h1></h1><p class=\"lead\">Ihr seid das Projektleitungsteam: In <b>12 Wochen</b> soll NovaCare bei drei Pilotkunden starten.</p><div class=\"b3new-cards\"><article><h3>Pflichtumfang</h3><p>Störungen melden, Status einsehen, Wartungen buchen; Schnittstelle zum Bestandssystem; Datenschutz und menschliche Qualitätskontrolle.</p></article><article><h3>Ressourcen</h3><p>Acht vorhandene Mitarbeitende mit begrenzter Kapazität. <b>30 Budgetpunkte</b> für zusätzliche Maßnahmen. Die KI-Ticketpriorisierung ist optional.</p></article></div><p class=\"callout\">Euer Ziel: <b>alle Pflicht-Skills auf Mindestniveau abdecken</b>, innerhalb von 12 Wochen und 30 Budgetpunkten.</p></section>"},{"id":"b3c1-requirements","title":"Welche Skills braucht NovaCare?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · NOVAWORKS · PLANSPIEL</div><h1>Welche Skills braucht NovaCare?</h1><p class=\"lead\">Pflichtumfang: Kundenportal, Bestands-Schnittstelle, Datenschutz, Ticketprozess und geprüfte Qualität. KI-Priorisierung ist optional.</p><p>Bewertung: Skillniveau <b>0 = keine Kenntnisse, 1 = Grundlagen, 2 = selbstständig, 3 = Expertenniveau</b>. Kapazitätspunkte stehen für den verfügbaren Projekteinsatz über zwölf Wochen – nicht für Geld.</p><div class=\"b3new-cards\"><article><h3>Pflicht-Skills · Mindestniveau · Bedarf</h3><p>Backend/API: <b>3 · 8 Kap.</b><br>UX/Portal: <b>2 · 5 Kap.</b><br>Kundenservice: <b>2 · 5 Kap.</b><br>Datenschutz: <b>3 · 3 Kap.</b></p></article><article><h3>Weitere Pflicht-Skills</h3><p>Prozess-/Ticketdesign: <b>2 · 5 Kap.</b><br>Testen/Qualitätssicherung: <b>2 · 4 Kap.</b><br><b>Optional:</b> KI-Priorisierung: 2 · 5 Kap.</p></article></div><p class=\"callout\">Prüft für jede Pflichtaufgabe <b>Skillniveau und verfügbare Kapazität</b>. Fehlt eines davon, entsteht eine Lücke.</p></section>"},{"id":"b3c1-profiles","title":"Die acht Skillprofile","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · NOVAWORKS · PLANSPIEL</div><h1>Die acht Skillprofile</h1><p class=\"lead\">Öffnet die acht Profile. Verfügbare Kapazität ist je Person begrenzt; eine Person kann ihre Punkte auf mehrere Aufgaben verteilen.</p><div class=\"b3new-body\"><details><summary><b>Ada</b> · Kundenservice · 7 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> Kundenservice 3; Testen 1; UX 1</p><p><b>Hinweis:</b> Kundenfälle und Abnahmetests</p></details><details><summary><b>Ben</b> · Datenanalyse · 5 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> Testen/QA 2; Prozessdesign 1; Datenanalyse 3</p><p><b>Hinweis:</b> Kann Testfälle und Qualitätsnachweise koordinieren</p></details><details><summary><b>Cem</b> · Prozessdesign · 6 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> Prozessdesign 3; Kundenservice 2; UX 1</p><p><b>Hinweis:</b> Verantwortet Ticketabläufe</p></details><details><summary><b>Dina</b> · UX/Produkt · 5 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> UX/Portal 3; Testen 1; Kundenservice 1</p><p><b>Hinweis:</b> Erstellt klickbaren Portalprototyp</p></details><details><summary><b>Eva</b> · KI-Prototypen · 4 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> KI-Integration 2; Testen 1; Backend/API 1</p><p><b>Hinweis:</b> KI-Ergebnisse müssen separat kontrolliert werden</p></details><details><summary><b>Finn</b> · IT-Sicherheit · 3 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> Datenschutz 3; IT-Sicherheit 3; Backend/API 1</p><p><b>Hinweis:</b> Datenschutzfreigabe; keine produktive Schnittstellenentwicklung</p></details><details><summary><b>Gina</b> · Projektleitung · 4 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> Koordination 3; Prozessdesign 1; Testen 1</p><p><b>Hinweis:</b> Plant Meilensteine; keine zusätzliche technische Umsetzung</p></details><details><summary><b>Hao</b> · Kommunikation · 5 Kapazitätspunkte</summary><p><b>Skills (Niveau 0–3):</b> Kundenservice 2; UX 1; Testen 1</p><p><b>Hinweis:</b> Kundenschulung und Kommunikation</p></details></div><p class=\"callout\">Alle Angaben sind fiktiv. Für nicht genannte Skills gilt Niveau 0. Kapazitätspunkte werden <b>nicht</b> vom Maßnahmenbudget abgezogen.</p></section>"},{"id":"b3c1-rules","title":"NovaWorks: verbindliche Spielregeln","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · NOVAWORKS · PLANSPIEL</div><h1></h1><p class=\"lead\">Die Kosten sind <b>fiktive Spielpunkte</b>. Interne Teamkapazitäten sind separat und kosten 0 Budgetpunkte.</p><div class=\"b3new-cards\"><article><h3>HIRE · 20 Punkte</h3><p>Eine Fachkraft für <b>einen</b> fehlenden Skill; verfügbar ab Woche 9; liefert bis zu 8 Kapazitätspunkte auf Niveau 3.</p></article><article><h3>TRAIN · 8 Punkte</h3><p>Eine vorhandene Person verbessert <b>einen</b> Skill um eine Stufe (max. 3); ab Woche 7; Kapazität bleibt unverändert.</p></article><article><h3>AI · 12 Punkte</h3><p>Unterstützt ab Woche 4 eine optionale Routineaufgabe; ersetzt weder die Pflicht-Skills noch die Qualitätsprüfung.</p></article><article><h3>PARTNER · 15 Punkte</h3><p>Deckt <b>einen</b> Pflicht-Skill auf Niveau 3 mit bis zu 8 Kapazitätspunkten ab; Lieferung ab Woche 6.</p></article><article><h3>STOP · 0 Punkte</h3><p>Nur <b>optionale</b> Funktionen verschieben; Pflichtumfang und Datenschutz bleiben verbindlich.</p></article></div><p class=\"callout\">Qualitätsnachweis: benannte Person prüft Portal, Schnittstelle, Datenschutz und Ticketbearbeitung. <b>Maximal 30 Punkte; Launch in Woche 12.</b></p></section>"},{"id":"b3c1-game","title":"NovaWorks: Arbeitsauftrag","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · NOVAWORKS · PLANSPIEL</div><h1></h1><p class=\"lead\">25 Minuten · Gruppen von 3–5 · Ihr entscheidet über die Besetzung des NovaCare-Piloten.</p><ol><li><b>5 Min – Soll/Ist-Vergleich:</b> Vergleicht die Skill-Anforderungen mit den acht Profilen. Welche Pflichtaufgaben sind nicht ausreichend abgedeckt?</li><li><b>5 Min – Intern besetzen:</b> Ordnet jeder Pflichtaufgabe eine Person und Kapazitätspunkte zu. Eine Person darf ihre verfügbare Kapazität nicht überschreiten.</li><li><b>10 Min – Lücken schließen:</b> Wählt Hire, Train, AI, Partner oder Stop; beachtet Kosten, Wirkung ab Woche und Mindestniveau.</li><li><b>5 Min – Entscheidung begründen:</b> Erstellt euren Launchplan und nennt ein verbleibendes Risiko.</li></ol><div class=\"b3new-task\"><h3>Abgabe: eine Entscheidungstabelle</h3><p><b>Aufgabe | Verantwortlich | Soll-Skill | vorhandener Skill | Kapazität | Maßnahme | Budget | ab Woche | Qualitätsprüfung</b></p><p>Ergänzt <b>Budgetsumme (≤ 30)</b>, <b>Launchentscheidung (ja/nein)</b> und <b>ein Risiko</b>.</p></div><p class=\"callout\">Prüffrage: Wer übernimmt die Schnittstellenentwicklung auf Niveau 3? Welche Optionen sind für diese Lücke wirklich geeignet?</p></section>"},{"id":"b3c1-debrief","title":"NovaWorks: Auswertung","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · NOVAWORKS · PLANSPIEL</div><h1></h1><h2>Vergleicht eure Entscheidungen</h2><p>Eine mögliche Lösung: <b>Partner</b> übernimmt Backend/API (15 Punkte, ab Woche 6); die internen Mitarbeitenden decken UX, Kundenservice, Datenschutz, Prozesse und QA ab. <b>KI-Priorisierung wird verschoben (Stop)</b>. Budget: <b>15 von 30 Punkten</b>.</p><p>Beispiel für die interne Kapazitätszuordnung: Dina 5 UX; Ada 5 Kundenservice; Finn 3 Datenschutz; Cem 5 Prozessdesign; Ben 4 QA. Die übrigen Personen unterstützen Koordination und Pilotkommunikation.</p><div class=\"b3new-task\"><h3>Diskussion</h3><ol><li>Warum wäre HIRE für die Schnittstelle möglich, aber zeitlich riskanter?</li><li>Welche Risiken entstehen durch einen externen Partner und wie sichert ihr die Übergabe?</li><li>Welche Option würdet ihr bei einem dauerhaften Rollout statt einem Pilot bevorzugen?</li></ol></div><p class=\"callout\">Überleitung: <b>Die richtigen Skills sind vorhanden – aber wie arbeiten diese Menschen als Team zusammen?</b></p></section>"},{"id":"b3c2-intro-bridge","title":"Warum wir über Generationen sprechen","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · EINSTIEG</div><h1>Warum wir über Generationen sprechen</h1><div class=\"b3-layout\"><div><p class=\"lead\">Zwei Entwicklungen treffen aufeinander: Viele erfahrene Beschäftigte verlassen den Arbeitsmarkt, gleichzeitig arbeiten mehrere Altersgruppen zusammen.</p><div class=\"stack-cards\"><article><strong>Demografie:</strong> Wie groß wird die Nachbesetzungslücke?</article><article><strong>Zusammenarbeit:</strong> Welche Unterschiede sind real – welche bloße Klischees?</article></div><p><strong>Fahrplan:</strong> 4 Schätzfragen → humorvoller Videoclip → Myth-Buster → wissenschaftliche Einordnung.</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Generationen im Arbeitsmarkt\"></figure></div></section>"},{"id":"b3c2-est-retire","title":"Wie viele erreichen das Rentenalter?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wie viele erreichen das Rentenalter?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Wie viele Erwerbspersonen in Deutschland werden bis 2040 das gesetzliche Rentenalter von 67 Jahren überschritten haben?</p><p><strong>Erst schätzen:</strong> Jede Person notiert eine Zahl. Danach Lösung aufdecken und Konsequenzen diskutieren.</p><details class=\"b3-est-answer\"><summary>Lösung aufdecken</summary><div class=\"big-stat\">13,3 Mio.</div><p>Das sind rund 30 % der Erwerbspersonen von 2025. Es handelt sich nicht um eine Prognose tatsächlicher Renteneintritte im selben Zeitraum.</p><p class=\"b3-source\">Quelle: Destatis, 23.06.2026, Mikrozensus 2025; https://ebs.publicnow.com/view/F4D87E3ACA7CB3BEB1127E3E9C023CDC03DAD67E</p></details></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Generationen und demografischer Wandel\"></figure></div></section>"},{"id":"b3c2-est-percent","title":"Wie groß ist die Rentenwelle?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wie groß ist die Rentenwelle?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Wie viel Prozent der Erwerbspersonen von 2025 entspricht die Gruppe, die bis 2040 das gesetzliche Rentenalter überschreiten wird?</p><p><strong>Erst schätzen:</strong> Jede Person notiert eine Zahl. Danach Lösung aufdecken und Konsequenzen diskutieren.</p><details class=\"b3-est-answer\"><summary>Lösung aufdecken</summary><div class=\"big-stat\">30 %</div><p>Fast jede dritte Person aus dem heutigen Erwerbspersonenbestand erreicht bis 2040 die gesetzliche Altersgrenze. Das bedeutet nicht, dass alle diese Stellen unbesetzt bleiben.</p><p class=\"b3-source\">Quelle: Destatis, 23.06.2026; https://ebs.publicnow.com/view/F4D87E3ACA7CB3BEB1127E3E9C023CDC03DAD67E</p></details></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Generationen und demografischer Wandel\"></figure></div></section>"},{"id":"b3c2-est-gap","title":"Wie groß könnte die Arbeitskräftelücke werden?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wie groß könnte die Arbeitskräftelücke werden?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Um wie viele Personen könnte das Erwerbspersonenpotenzial in Deutschland bis 2036 laut IW-Prognose sinken?</p><p><strong>Erst schätzen:</strong> Jede Person notiert eine Zahl. Danach Lösung aufdecken und Konsequenzen diskutieren.</p><details class=\"b3-est-answer\"><summary>Lösung aufdecken</summary><div class=\"big-stat\">4,3 Mio.</div><p>Prognose eines demografischen Potenzialrückgangs, nicht gleichzusetzen mit 4,3 Mio. offenen Stellen. Migration, Erwerbsbeteiligung und Produktivität können die tatsächliche Entwicklung verändern.</p><p class=\"b3-source\">Quelle: Institut der deutschen Wirtschaft, 15.06.2026; https://www.iwkoeln.de/presse/pressemitteilungen/babyboomer-in-rente-bis-2036-fehlen-43-millionen-arbeitskraefte.html</p></details></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Generationen und demografischer Wandel\"></figure></div></section>"},{"id":"b3c2-est-age","title":"Wie alt ist Deutschland 2035?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wie alt ist Deutschland 2035?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Welcher Anteil der Bevölkerung Deutschlands wird 2035 voraussichtlich mindestens 67 Jahre alt sein?</p><p><strong>Erst schätzen:</strong> Jede Person notiert eine Zahl. Danach Lösung aufdecken und Konsequenzen diskutieren.</p><details class=\"b3-est-answer\"><summary>Lösung aufdecken</summary><div class=\"big-stat\">ca. 25 %</div><p>Das ist rund jede vierte Person. Im Jahr 2024 lag der Anteil bei rund 20 %. Bevölkerung im Rentenalter ist nicht gleichbedeutend mit tatsächlichen Rentenbeziehenden.</p><p class=\"b3-source\">Quelle: Destatis, 11.12.2025, 16. koordinierte Bevölkerungsvorausberechnung; https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/12/PD25_446_12.html</p></details></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Generationen und demografischer Wandel\"></figure></div></section>"},{"id":"b3c2-est-boomers","title":"Wie viele Babyboomer leben in Deutschland?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wie viele Babyboomer leben in Deutschland?</h1><p class=\"lead\">Wie viel Prozent der gesamten Bevölkerung in Deutschland gehören zur Babyboomer-Generation?</p><details class=\"b3-reveal\"><summary>Antwort aufdecken</summary><div class=\"callout\"><b>22,3 % (Ipsos 2026)</b><p>Deutschland: 22,27 %. Weltweit rund 12,8 % (UN-basierte Auswertung, Datenstand Ende 2024). Die Abgrenzungen der Geburtsjahrgänge unterscheiden sich je nach Quelle; Werte sind deshalb nur näherungsweise vergleichbar.</p></div></details></section>"},{"id":"b3c2-est-genz","title":"Wie groß ist die Generation Z?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wie groß ist die Generation Z?</h1><p class=\"lead\">Wie viel Prozent der gesamten Bevölkerung gehören in Deutschland zur Gen Z – und wie viel weltweit?</p><details class=\"b3-reveal\"><summary>Antwort aufdecken</summary><div class=\"callout\"><b>Deutschland 15,9 % · weltweit etwa 22,9 %</b><p>Ipsos 2026: Deutschland 15,89 %. Weltweit: 22,9 % (UN-basierte Auswertung für 2024). Jüngere Bevölkerungsstrukturen prägen die weltweite Verteilung.</p></div></details></section>"},{"id":"b3c2-est-alpha","title":"Wer stellt weltweit die größte junge Kohorte?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · SCHÄTZFRAGE</div><h1>Wer stellt weltweit die größte junge Kohorte?</h1><p class=\"lead\">Wie hoch ist der Anteil der Generation Alpha an der Weltbevölkerung (Stand Ende 2024)?</p><details class=\"b3-reveal\"><summary>Antwort aufdecken</summary><div class=\"callout\"><b>Rund 24,4 %</b><p>In Deutschland weist Ipsos 2026 für Generation Alpha rund 13,0 % aus. Die Daten nutzen nicht überall exakt dieselben Geburtsjahrgrenzen; die Gegenüberstellung zeigt die Größenordnung.</p></div></details></section>"},{"id":"b3c2-demography-compare","title":"Generationen in Deutschland und weltweit","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · DEMOGRAFIE IM VERGLEICH</div><h1>Deutschland ist älter als die Welt</h1><p class=\"lead\">Anteil an der <b>Gesamtbevölkerung</b>, gerundet in Prozent. Die Werte sind eine Orientierung, keine Arbeitsmarktquoten.</p><div class=\"b3-card-grid\"><div class=\"b3-card\"><h3>Deutschland · Ipsos 2026</h3><p>Babyboomer <b>22,3 %</b><br>Gen X <b>21,8 %</b><br>Millennials <b>20,3 %</b><br>Gen Z <b>15,9 %</b><br>Gen Alpha <b>13,0 %</b></p></div><div class=\"b3-card\"><h3>Welt · UN-basierte Auswertung 2024</h3><p>Babyboomer <b>12,8 %</b><br>Gen X <b>16,7 %</b><br>Millennials <b>21,2 %</b><br>Gen Z <b>22,9 %</b><br>Gen Alpha <b>24,4 %</b></p></div></div><p class=\"callout\"><b>Was fällt auf?</b> In Deutschland sind Babyboomer anteilig deutlich stärker vertreten; weltweit sind die jüngeren Kohorten größer. Daraus folgen unterschiedliche Herausforderungen für Rentensysteme, Nachwuchsgewinnung und Weiterbildung.</p><p class=\"source\">Quellen: Ipsos Generations Report 2026, S. 49; Visual Capitalist/UN WPP 2024, veröffentlicht 2025. Achtung: Generationsgrenzen weichen leicht voneinander ab. <a href=\"https://resources.ipsos.com/rs/297-CXJ-795/images/Ipsos-Generations-Report-2026.pdf\" target=\"_blank\" rel=\"noopener\">Ipsos</a> · <a href=\"https://www.visualcapitalist.com/ranked-the-worlds-population-by-generation/\" target=\"_blank\" rel=\"noopener\">Weltweite Auswertung</a></p></section>"},{"id":"b3c2-video","title":"Boomer trifft Gen Z: Klischees im Büro","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 2 · VIDEO & DISKUSSION</div><h1>Boomer trifft Gen Z: Klischees im Büro</h1><div class=\"b3-layout\"><div><p class=\"lead\">Humorvoller Einstieg: Welche Stereotype werden überzeichnet?</p><div class=\"b3-video-frame\"><iframe src=\"https://www.youtube-nocookie.com/embed/_ZQhvfhmybY\" title=\"AgentZ: Das Büro besetzen – Gen Z und Boomer\" loading=\"lazy\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe></div><p><a href=\"https://www.youtube.com/watch?v=_ZQhvfhmybY\" target=\"_blank\" rel=\"noopener noreferrer\">Video auf YouTube öffnen (falls Einbettung blockiert ist)</a></p><p><strong>Diskussion (2 Min.):</strong> Welche Aussagen sind reine Klischees? Welche Beobachtungen könnte man empirisch prüfen?</p><small>Quelle: AgentZ, „Das Büro besetzen“, YouTube, 10.08.2025. Humoristische Darstellung, keine empirische Evidenz.</small></div></div></section>"},{"id":"b3c2-start","title":"Generationen & neue Karrierebilder","html":"<section class=\"scene-inner b3-scene chapter-cover\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2</div><h1>Generationen & neue Karrierebilder</h1><div class=\"b3-layout\"><div><p class=\"lead\">Sind Generationen wirklich so verschieden – oder erzählen wir uns zu einfache Geschichten?</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Alter, Lebensphase und Zeitgeist auseinanderhalten\"><figcaption>Alter, Lebensphase und Zeitgeist auseinanderhalten</figcaption></figure></div></section>"},{"id":"b3c2-data","title":"Money · Meaning · Well-being","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 2 · DELOITTE 2025</div><h1>Money · Meaning · Well-being</h1><div class=\"b3-layout\"><div><div class=\"big-stat\">6 %</div><p>der befragten Gen Z und Millennials nannten Führung als <strong>primäres</strong> Karriereziel. 89 % der Gen Z und 92 % der Millennials betrachteten Purpose als wichtig für Arbeitszufriedenheit und Wohlbefinden.</p><div class=\"source-note\">Deloitte Global Gen Z and Millennial Survey 2025 · 23.482 Befragte, 44 Länder; Selbstbericht · <a href=\"https://www.deloitte.com/us/en/insights/topics/talent/2025-gen-z-millennial-survey.html\" target=\"_blank\" rel=\"noopener\">Quelle öffnen ↗</a></div></div><figure class=\"b3-visual\"><img src=\"assets/block3/generation_lens.svg\" alt=\"Generationenbefunde nicht mit Kausalität verwechseln\"><figcaption>Generationenbefunde nicht mit Kausalität verwechseln</figcaption></figure></div></section>"},{"id":"b3c2-2026","title":"Führung ja – aber nachhaltig","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 2 · WAS MOTIVIERT JUNGE BESCHÄFTIGTE?</div><h1>Karriere ≠ Chefposten</h1><div class=\"b3-layout\"><div><div class=\"big-stat\">6 %</div><p><strong>Nur etwa 6 %</strong> der befragten Gen Z und Millennials nennen eine Führungsposition als ihr wichtigstes Karriereziel – das heißt nicht, dass 94 % Führung grundsätzlich ablehnen.</p><div class=\"compare\"><div><h3>Was viele suchen</h3><p>Entwicklung, sinnvolle Arbeit, finanzielle Sicherheit und Vereinbarkeit.</p></div><div><h3>Was Führung unattraktiv macht</h3><p>Hohe Belastung, ständige Erreichbarkeit, unklare Verantwortung.</p></div></div><p class=\"callout\"><strong>Diskussion:</strong> Wie müsste eine Führungsrolle gestaltet sein, damit ihr sie übernehmen würdet?</p><div class=\"source-note\">Deloitte Global Gen Z and Millennial Survey 2026 · <a href=\"https://www.deloitte.com/global/en/about/press-room/deloitte-2026-gen-z-and-millennial-survey.html\" target=\"_blank\" rel=\"noopener\">Quelle und Methodik ↗</a></div></div></div></section>"},{"id":"b3c3-start","title":"New Leadership","html":"<section class=\"scene-inner b3-scene chapter-cover\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 3</div><h1>New Leadership</h1><div class=\"b3-layout\"><div><p class=\"lead\">Wenn Arbeit flexibler, digitaler und selbstorganisierter wird, verschwindet Führung nicht. Ihre Aufgabe verändert sich.</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/leadership_compass.svg\" alt=\"Orientierung, Vertrauen, Coaching und Accountability\"><figcaption>Orientierung, Vertrauen, Coaching und Accountability</figcaption></figure></div></section>"},{"id":"b3c3-manager","title":"Führung hat messbaren Einfluss","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 3 · FÜHRUNG WIRKT</div><h1>70 % – was bedeutet das wirklich?</h1><div class=\"b3-layout\"><div><div class=\"big-stat\">70 %</div><p><strong>Gallups Aussage:</strong> Die Führungskraft erklärt in den untersuchten Daten ungefähr 70 % der <em>Unterschiede im Mitarbeiterengagement zwischen Teams</em>.</p><div class=\"compare\"><div><h3>Das bedeutet es</h3><p>Teams unterscheiden sich stark darin, wie engagiert sie sind. Führungsverhalten ist dabei ein wesentlicher Einflussfaktor.</p></div><div><h3>Das bedeutet es NICHT</h3><p>Nicht: „70 % der Leistung eines Mitarbeiters kommen vom Chef.“ Auch keine exakte Kausalaussage für jedes einzelne Team.</p></div></div><p class=\"callout\"><strong>Praxisfrage:</strong> Zwei Teams haben ähnliche Aufgaben, aber völlig unterschiedliche Motivation. Was könnte die Führung anders machen?</p><div class=\"source-note\">Gallup · <a href=\"https://www.gallup.com/workplace/395210/engage-frontline-managers.aspx\" target=\"_blank\" rel=\"noopener\">Hintergrund und Studie ↗</a></div></div></div></section>"},{"id":"b3c3-shift","title":"Boss → Coach? Zu einfach.","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 3 · FÜHRUNG IM VERGLEICH</div><h1>Ein Team, zwei Führungsstile</h1><div class=\"b3-layout\"><div><p class=\"lead\">NovaWorks: Der Produktstart ist gefährdet. Ein Fehler im KI-System wurde zu spät entdeckt.</p><div class=\"compare\"><div><h3>Chefmodus: Kontrolle</h3><p>„Ab sofort geht jede Entscheidung über meinen Tisch. Ich will täglich einen Bericht.“</p><p><strong>Mögliche Folge:</strong> Mehr Freigaben, langsamere Entscheidungen, weniger Eigeninitiative.</p></div><div><h3>Coaching mit Verantwortung</h3><p>„Wer prüft künftig KI-Ergebnisse? Welche Freigabegrenzen und Eskalationswege brauchen wir?“</p><p><strong>Mögliche Folge:</strong> Klare Verantwortung und schnelleres Lernen – braucht Vertrauen und Regeln.</p></div></div><p class=\"callout\"><strong>Mini-Abstimmung (2 Min):</strong> Welcher Ansatz hilft in dieser Krise? Wann ist direkte Anweisung trotzdem sinnvoll?</p></div></div></section>"},{"id":"b3c3-inbox","title":"The Leadership Inbox","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">MISSION 15 · PLANSPIEL · 25 MIN</div><h1>Leadership Inbox: Euer Führungsauftrag</h1><div class=\"b3-layout\"><div><p class=\"lead\">Ihr seid die neue Führung des NovaWorks-Teams. In 12 Wochen soll NovaCare starten. Das Team ist angespannt; fünf Nachrichten landen in eurem Posteingang.</p><div class=\"compare\"><div><h3>Eure Aufgabe</h3><p><strong>1.</strong> Lest alle fünf Fälle.<br><strong>2.</strong> Entscheidet je Fall: Was tut ihr innerhalb von 24 Stunden?<br><strong>3.</strong> Begründet eure Entscheidung und nennt ein Risiko.<br><strong>4.</strong> Legt eine Verantwortlichkeit und einen nächsten Prüftermin fest.</p></div><div><h3>Abgabe pro Fall</h3><p><strong>Entscheidung</strong> · <strong>Begründung</strong> · <strong>Nebenwirkung</strong> · <strong>Verantwortliche Person</strong> · <strong>Kontrollpunkt</strong></p><p>Gruppen: 3–5 Personen · 15 Min Bearbeitung · 10 Min Austausch.</p></div></div><p class=\"callout\">Die konkreten Nachrichten und Zusatzinformationen stehen auf der <strong>nächsten Folie</strong>.</p></div></div></section>"},{"id":"b3c3-inbox-cases","title":"Leadership Inbox: fünf Nachrichten","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">MISSION 15 · FALLKARTEN</div><h1>Fünf Nachrichten – fünf Entscheidungen</h1><div class=\"b3-layout\"><div><div class=\"stack-cards\"><details><summary><strong>1 · Hybrid-Konflikt</strong></summary><p>Thomas ist an drei Tagen im Büro, Mia überwiegend remote. Thomas beklagt verzögerte Abstimmung; Mia erhält kurzfristige Termine ohne Vorlauf. <strong>Auftrag:</strong> Welche Teamregel und welcher Eskalationsweg helfen?</p></details><details><summary><strong>2 · High Performer will Verantwortung</strong></summary><p>Daniel möchte die technische Teilprojektleitung übernehmen. Er liefert gute Ergebnisse, hat aber noch keine Führungserfahrung. <strong>Auftrag:</strong> Was delegiert ihr und welche Unterstützung braucht er?</p></details><details><summary><strong>3 · KI-Agent macht Fehler</strong></summary><p>Ein KI-Vorschlag wurde ungeprüft an einen Kunden weitergegeben. Die Ursache und der Schaden sind noch unklar. <strong>Auftrag:</strong> Was stoppt ihr sofort, wer prüft, wer informiert den Kunden?</p></details><details><summary><strong>4 · Team überlastet</strong></summary><p>Sechs Wochen vor einem Meilenstein häufen sich Überstunden und Fehler. Zwei Aufgaben konkurrieren um dieselben Spezialisten. <strong>Auftrag:</strong> Was priorisiert oder verschiebt ihr?</p></details><details><summary><strong>5 · Widerstand gegen Veränderung</strong></summary><p>Sabine hält den neuen KI-gestützten Prozess für intransparent und befürchtet Qualitätsverlust. <strong>Auftrag:</strong> Wie bindet ihr ihre Expertise ein, ohne den Wandel zu blockieren?</p></details></div><p class=\"callout\"><strong>Wichtig:</strong> Keine perfekte Musterlösung. Beurteilt Wirkung auf Qualität, Fairness, Vertrauen und Verantwortung.</p></div></div></section>"},{"id":"b3c3-score","title":"Nicht richtig/falsch – sondern Konsequenzen","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">MISSION 15 · AUSWERTUNG</div><h1>Was kostet eure Entscheidung?</h1><div class=\"b3-layout\"><div><p>Vergleicht zwei ausgewählte Fälle im Plenum. Welche Entscheidung würdet ihr nach der Diskussion ändern?</p><div class=\"four-cols\"><b>QUALITÄT</b><b>FAIRNESS</b><b>VERTRAUEN</b><b>VERANTWORTUNG</b></div><p><strong>Leitfragen:</strong> Wer trägt das Risiko? Welche Informationen fehlen? Wie merkt ihr in einer Woche, ob eure Maßnahme funktioniert?</p><p class=\"callout\">Führung bedeutet nicht nur Coaching, sondern auch klare Entscheidungen, Schutz des Teams und Rechenschaft.</p></div></div></section>"},{"id":"b3c4-start","title":"Frauen, Macht & Führung","html":"<section class=\"scene-inner k4-slide k4-cover\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>EINSTIEG</span></div><div class=\"k4-hero\"><div><div class=\"k4-eyebrow\">FRAUEN · MACHT · FÜHRUNG</div><h2>Wer bekommt die nächste Führungsposition?</h2><p>Kompetenz, Netzwerke, Lebensläufe und KI: Was bestimmt den Aufstieg wirklich?</p><div class=\"k4-pillrow\"><span>Skills</span><span>Generationen</span><span>New Leadership</span></div></div><img src=\"assets/editorial/collaboration.jpg\" alt=\"Menschen arbeiten im Team\"/></div></section>"},{"id":"b3k4-est1","title":"Schätzfrage 1 · Führung in Deutschland","html":"<section class=\"scene-inner k4-slide k4-estimate\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>WISSENS-CHECK</span></div><div class=\"k4-est-layout\"><div class=\"k4-est-main\"><div class=\"k4-eyebrow\">SCHÄTZFRAGE 1 / 4</div><h2>Wie hoch ist der Frauenanteil in Führungspositionen in Deutschland?</h2><div class=\"k4-options\"><span class=\"k4-option\">20 %</span><span class=\"k4-option\">30 %</span><span class=\"k4-option\">40 %</span><span class=\"k4-option\">50 %</span></div><button class=\"reveal-btn k4-reveal\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card k4-answer\" hidden><strong>29,1 %</strong><p>Deutschland, Bezugsjahr 2024. Gerundet liegt die richtige Schätzung bei 30 %.</p><small>Destatis / Eurostat · 2024</small></div></div><div class=\"k4-est-graphic\"><div class=\"k4-num\">1<span>/4</span></div><div class=\"k4-circle\"></div><p>Erst schätzen.<br>Dann diskutieren.</p></div></div></section>"},{"id":"b3k4-est2","title":"Schätzfrage 2 · Deutschland und EU","html":"<section class=\"scene-inner k4-slide k4-estimate\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>WISSENS-CHECK</span></div><div class=\"k4-est-layout\"><div class=\"k4-est-main\"><div class=\"k4-eyebrow\">SCHÄTZFRAGE 2 / 4</div><h2>Wie groß ist der Abstand zwischen Deutschland und dem EU-Durchschnitt?</h2><div class=\"k4-options\"><span class=\"k4-option\">Deutschland 6 Prozentpunkte darunter</span><span class=\"k4-option\">Deutschland 6 Punkte darüber</span><span class=\"k4-option\">Beide etwa gleich</span><span class=\"k4-option\">Deutschland 15 Punkte darunter</span></div><button class=\"reveal-btn k4-reveal\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card k4-answer\" hidden><strong>Rund 6 Prozentpunkte darunter</strong><p>Deutschland: 29,1 %. EU: rund 35 % (2024). Der Vergleich allein erklärt noch keine Ursachen.</p><small>Eurostat / Destatis · 2024</small></div></div><div class=\"k4-est-graphic\"><div class=\"k4-num\">2<span>/4</span></div><div class=\"k4-circle\"></div><p>Erst schätzen.<br>Dann diskutieren.</p></div></div></section>"},{"id":"b3k4-est3","title":"Schätzfrage 3 · Die erste Beförderung","html":"<section class=\"scene-inner k4-slide k4-estimate\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>WISSENS-CHECK</span></div><div class=\"k4-est-layout\"><div class=\"k4-est-main\"><div class=\"k4-eyebrow\">SCHÄTZFRAGE 3 / 4</div><h2>Auf 100 Männer, die erstmals ins Management befördert werden: Wie viele Frauen kommen?</h2><div class=\"k4-options\"><span class=\"k4-option\">70</span><span class=\"k4-option\">80</span><span class=\"k4-option\">93</span><span class=\"k4-option\">100</span></div><button class=\"reveal-btn k4-reveal\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card k4-answer\" hidden><strong>93 Frauen</strong><p>Der Wert beschreibt Beförderungen in untersuchten US-Unternehmen, nicht den Frauenanteil im Management. Beispiel: Werden 100 Männer befördert, sind es 93 Frauen – trotz ähnlicher Ausgangspositionen.</p><small>McKinsey &amp; LeanIn.Org · Women in the Workplace 2025 · USA</small></div></div><div class=\"k4-est-graphic\"><div class=\"k4-num\">3<span>/4</span></div><div class=\"k4-circle\"></div><p>Erst schätzen.<br>Dann diskutieren.</p></div></div></section>"},{"id":"b3k4-est4","title":"Schätzfrage 4 · Der Thomas-Effekt","html":"<section class=\"scene-inner k4-slide k4-estimate\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>WISSENS-CHECK</span></div><div class=\"k4-est-layout\"><div class=\"k4-est-main\"><div class=\"k4-eyebrow\">SCHÄTZFRAGE 4 / 4</div><h2>Gab es 2019 in untersuchten deutschen Vorständen mehr Männer namens Thomas oder Michael als Frauen insgesamt?</h2><div class=\"k4-options\"><span class=\"k4-option\">Ja</span><span class=\"k4-option\">Nein</span></div><button class=\"reveal-btn k4-reveal\" type=\"button\">Antwort auflösen</button><div class=\"reveal-card k4-answer\" hidden><strong>Ja</strong><p>Die AllBright Stiftung nutzte diesen Vergleich, um homogene Führungsgremien zu veranschaulichen. Historische Momentaufnahme, keine Aussage über 2026.</p><small>AllBright Stiftung · 2019</small></div></div><div class=\"k4-est-graphic\"><div class=\"k4-num\">4<span>/4</span></div><div class=\"k4-circle\"></div><p>Erst schätzen.<br>Dann diskutieren.</p></div></div></section>"},{"id":"b3k4-data","title":"Von der Zahl zur Karrierepipeline","html":"<section class=\"scene-inner k4-slide k4-diagram\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>KARRIEREPIPELINE</span></div><h1>Die Karrierepipeline hat mehrere Engstellen</h1><p class=\"k4-intro\">Nicht nur die Spitze zählt: An welcher Stelle verlieren Organisationen weibliche Talente?</p><div class=\"k4-pipeline\"><div><b>01</b><strong>Talentpool</strong><span>Wer bewirbt sich?</span></div><div><b>02</b><strong>Erste Führung</strong><span>Wer wird befördert?</span></div><div><b>03</b><strong>Topmanagement</strong><span>Wer steigt weiter auf?</span></div><div><b>04</b><strong>Geschäftsführung</strong><span>Wer entscheidet?</span></div></div><div class=\"k4-bottomnote\">Messgrößen: Bewerbungs- und Beförderungsraten · Entwicklungsprojekte · Verbleib · Vergütung</div></section>"},{"id":"b3k4-broken","title":"Broken Rung: erste Beförderung","html":"<section class=\"scene-inner k4-slide k4-cards\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>ANALYSE</span></div><h1>Die erste Beförderung ist entscheidend</h1><p class=\"k4-intro\">Weniger Frauen im ersten Managementlevel bedeutet langfristig weniger potenzielle Kandidatinnen für höhere Positionen.</p><div class=\"k4-twocol\"><article class=\"k4-panel \"><h3>Mechanismus</h3><p>Unterschiedliche Beförderungswahrscheinlichkeiten wirken über Hierarchieebenen kumulativ.</p></article><article class=\"k4-panel \"><h3>Nicht verwechseln</h3><p>Ein beobachteter Zusammenhang erklärt noch nicht, ob Ursache Beurteilung, Projektzugang, Arbeitszeit oder Bewerbungsverhalten ist.</p></article><article class=\"k4-panel \"><h3>Anschluss an Skills</h3><p>Führungspotenzial über überprüfbare Verhaltensindikatoren und Ergebnisse statt über Sichtbarkeit bewerten.</p></article></div></section>"},{"id":"b3k4-care","title":"Lebensphasen, Care und Teilzeit","html":"<section class=\"scene-inner k4-slide k4-editorial\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PRAXIS & TRANSFER</span></div><h1>Nichtlineare Karrieren sind keine fehlende Kompetenz</h1><div class=\"k4-split k4-editorial\"><div class=\"k4-photo\"><img src=\"assets/editorial/teamwork.jpg\" alt=\"Menschen im Arbeitsumfeld\"/></div><div class=\"k4-stack\"><p class=\"k4-intro\">Elternzeit, Teilzeit und Pflegeverantwortung können beeinflussen, welche Projekte, Netzwerke und Führungsvertretungen erreichbar sind.</p><article class=\"k4-panel \"><h3>Verwechslungsgefahr</h3><p>Verfügbarkeit ≠ Leistung ≠ Führungspotenzial.</p></article><article class=\"k4-panel \"><h3>Organisationsfrage</h3><p>Welche Führungsaufgaben verlangen tatsächlich bestimmte Zeitfenster?</p></article><article class=\"k4-panel \"><h3>Kapitel-2-Bezug</h3><p>Lebensphase ist nicht dasselbe wie Generation; Stereotype über Mütter, Väter oder Alter prüfen.</p></article><article class=\"k4-panel \"><h3></h3><p>Einordnung: Forschungsfelder Gender Care Gap und Teilzeitkarrieren; keine fiktiven Zahlen als Studienbefunde.</p></article></div></div></section>"},{"id":"b3k4-thomas","title":"Thomas-Kreislauf und Ähnlichkeitsbias","html":"<section class=\"scene-inner k4-slide k4-diagram\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>ORGANISATION & BIAS</span></div><h1>Warum Ähnlichkeit Chancen erzeugen kann</h1><div class=\"k4-split\"><div class=\"k4-visual\"><div class=\"k4-loop\"><span>Ähnlichkeit</span><span>Empfehlung</span><span>Aufstieg</span><span>Neue Entscheider</span></div><p>Der „Thomas-Kreislauf“ veranschaulicht, wie sich homogene Netzwerke selbst verstärken können.</p></div><div class=\"k4-stack\"><article class=\"k4-panel \"><h3>Ähnlichkeitsbias</h3><p>Menschen bewerten ihnen vertraute Profile mitunter positiver.</p></article><article class=\"k4-panel \"><h3>Thomas-Kreislauf</h3><p>Populäre Bezeichnung der AllBright Stiftung für sich reproduzierende männlich geprägte Führungskreise.</p></article><article class=\"k4-panel \"><h3>Prüffrage</h3><p>Wer durfte bisher führen – und wer hatte nie die Gelegenheit, Führung nachzuweisen?</p></article></div></div></section>"},{"id":"b3k4-ai","title":"KI-Bias im Recruiting und bei Beförderungen","html":"<section class=\"scene-inner k4-slide k4-diagram\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>KI & FAIRNESS</span></div><h1>Wenn KI historische Entscheidungen kopiert</h1><div class=\"k4-split\"><div class=\"k4-stack\"><article class=\"k4-panel \"><h3>Dokumentierter Fall</h3><p>Amazon beendete ein experimentelles Recruiting-System, das aus historischen Lebensläufen lernte und bestimmte Hinweise auf weibliche Bewerbungen benachteiligte.</p></article><article class=\"k4-panel \"><h3>Proxy-Variablen</h3><p>Auch ohne Geschlechtsfeld können Vollzeitjahre, Empfehlungen oder Karriereunterbrechungen indirekt mit Geschlecht zusammenhängen.</p></article><article class=\"k4-panel \"><h3>Kontrolle</h3><p>Jobbezogene Merkmale definieren, Modelle auf Gruppenunterschiede prüfen, Entscheidungen dokumentieren und Menschen verantwortlich halten.</p></article><article class=\"k4-panel \"><h3>Rechtlicher Rahmen</h3><p>KI-Systeme für Beschäftigung und Personalmanagement werden im EU AI Act grundsätzlich als Hochrisiko-Anwendungsfall behandelt; konkrete Pflichten und Zeitpunkte gesondert prüfen.</p></article></div><div class=\"k4-visual k4-ai-flow\"><div>Historische Personalentscheidungen</div><span>↓</span><div>KI lernt Muster</div><span>↓</span><div>Risiko: verzerrte Empfehlungen</div><small>Fallbeispiel: Amazon-Recruiting-System (2018 bekannt geworden)</small></div></div></section>"},{"id":"b3k4-tools","title":"Was Unternehmen konkret ändern können","html":"<section class=\"scene-inner k4-slide k4-cards\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>ANALYSE</span></div><h1>Faire Karrierechancen entstehen durch Prozesse</h1><p class=\"k4-intro\">Nicht „Frauen reparieren“, sondern Entscheidungen nachvollziehbar machen.</p><div class=\"k4-twocol\"><article class=\"k4-panel \"><h3>Vor der Auswahl</h3><p>Stellenanforderungen, Gewichtungen und Bewertungsmaßstäbe verbindlich festlegen.</p></article><article class=\"k4-panel \"><h3>Während der Auswahl</h3><p>Strukturierte Interviews, mehrere Perspektiven und belegbare Verhaltensbeispiele.</p></article><article class=\"k4-panel \"><h3>Nach der Auswahl</h3><p>Beförderungsraten, Talentprogramme und Feedback nach Gruppen prüfen.</p></article><article class=\"k4-panel \"><h3>Sponsorship</h3><p>Aktive Förderung und Zugang zu sichtbaren Projekten statt bloßem Mentoring.</p></article></div></section>"},{"id":"b3k4-topsharing","title":"Topsharing und Führung in Teilzeit","html":"<section class=\"scene-inner k4-slide k4-editorial\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PRAXIS & TRANSFER</span></div><h1>Muss Führung zwingend Vollzeit bedeuten?</h1><div class=\"k4-split k4-editorial\"><div class=\"k4-photo\"><img src=\"assets/editorial/teamwork.jpg\" alt=\"Menschen im Arbeitsumfeld\"/></div><div class=\"k4-stack\"><p class=\"k4-intro\">Topsharing teilt eine Führungsfunktion auf zwei Personen – mit expliziter Verantwortung, Übergaben und gemeinsamen Zielen.</p><article class=\"k4-panel \"><h3>Chancen</h3><p>Mehr Talentpool, Vertretbarkeit und unterschiedliche Perspektiven.</p></article><article class=\"k4-panel \"><h3>Risiken</h3><p>Unklare Zuständigkeiten, zusätzlicher Abstimmungsbedarf und widersprüchliche Signale.</p></article><article class=\"k4-panel \"><h3>Kapitel-3-Bezug</h3><p>New Leadership heißt: Führung über Wirkung, Vertrauen und Koordination gestalten.</p></article><article class=\"k4-panel \"><h3>Mini-Frage</h3><p>Welche Aufgaben müssen eindeutig einer Person zugeordnet sein?</p></article></div></div></section>"},{"id":"b3k4-game-start","title":"Planspiel · The Promotion Decision","html":"<section class=\"scene-inner k4-slide k4-editorial\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PRAXIS & TRANSFER</span></div><h1>NovaWorks: Wer wird Teamleitung NovaCare?</h1><div class=\"k4-split k4-editorial\"><div class=\"k4-photo\"><img src=\"assets/editorial/collaboration.jpg\" alt=\"Menschen im Arbeitsumfeld\"/></div><div class=\"k4-stack\"><p class=\"k4-intro\">Ihr seid ein Beförderungsausschuss. Besetzt eine Stelle für 18 Mitarbeitende, Budget und digitale Transformation.</p><article class=\"k4-panel \"><h3>Gruppen</h3><p>4–5 Personen; eine Person protokolliert Entscheidungen.</p></article><article class=\"k4-panel \"><h3>Ablauf</h3><p>Runde 1: erste Auswahl (8 Min.) · Runde 2: neue Fakten (8 Min.) · Runde 3: KI-Audit (8 Min.) · Runde 4: Regeln und Pitch (10 Min.).</p></article><article class=\"k4-panel \"><h3>Abgabe</h3><p>Person + 3 begründete Kriterien + Gewichtung auf 100 Punkte + 3 Verfahrensregeln.</p></article><article class=\"k4-panel \"><h3>Spielregel</h3><p>Alle folgenden Personalprofile, KI-Scores und Leistungswerte sind ausdrücklich fiktive Planspieldaten.</p></article></div></div></section>"},{"id":"b3k4-game-profiles","title":"Planspiel · Vier Kandidaturen","html":"<section class=\"scene-inner k4-slide k4-people\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PLANSPIEL · RUNDE 1</span></div><h1>Vier Menschen, vier Karrierewege</h1><div class=\"k4-peoplegrid\"><article><div class=\"k4-avatar\">T</div><h3>Thomas, 43</h3><p>Senior Project Manager; 12 Jahre bei NovaWorks; Vollzeit; großes Netzwerk; mehrere Führungsvertretungen; solide Projektergebnisse.</p></article><article><div class=\"k4-avatar\">S</div><h3>Sarah, 38</h3><p>Product Owner; 9 Jahre Erfahrung; 30 Stunden/Woche; starke Teamfeedbacks; erfolgreiche Digitalprojekte; keine disziplinarische Führung.</p></article><article><div class=\"k4-avatar\">D</div><h3>Daniel, 32</h3><p>AI Transformation Lead; 5 Jahre im Unternehmen; hohe KI-Kompetenz; schnelle Karriere; wenig Konfliktmanagement-Erfahrung.</p></article><article><div class=\"k4-avatar\">M</div><h3>Miriam, 46</h3><p>Change Managerin; 15 Jahre Erfahrung; zwei erfolgreiche Transformationen; starke Coachingkompetenz; zwei Jahre außerhalb von NovaWorks.</p></article></div><div class=\"k4-bottomnote\">Arbeitsauftrag: Erste Wahl + drei Kriterien dokumentieren. Welche Informationen fehlen euch?</div></section>"},{"id":"b3k4-game-reveal","title":"Planspiel · Neue Informationen","html":"<section class=\"scene-inner k4-slide k4-cards\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PLANSPIEL · RUNDE 2</span></div><h1>Was sagt der Lebenslauf nicht?</h1><div class=\"k4-twocol\"><article class=\"k4-panel \"><h3>Neue Informationen aus strukturierten Interviews und Teamfeedbacks</h3><p>ändert ihr eure Wahl?</p></article><article class=\"k4-panel \"><h3>Thomas</h3><p>Führungsvertretungen entstanden durch persönliche Empfehlung; Teamfeedback durchschnittlich.</p></article><article class=\"k4-panel \"><h3>Sarah</h3><p>Fachliche Leitung eines interdisziplinären Teams; sehr gute Ergebnisse in Zusammenarbeit und Mitarbeiterentwicklung.</p></article><article class=\"k4-panel \"><h3>Daniel</h3><p>Starke wirtschaftliche Projektergebnisse; wiederholte kritische Rückmeldungen zum Umgang mit Konflikten.</p></article></div><div class=\"k4-bottomnote\">Diskutiert: Was hat eure Einschätzung verändert? Welche Annahmen waren ungesichert?</div></section>"},{"id":"b3k4-game-ai","title":"Planspiel · KI-Empfehlung prüfen","html":"<section class=\"scene-inner k4-slide k4-diagram\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PLANSPIEL · RUNDE 3</span></div><h1>TalentAI empfiehlt Thomas. Würdet ihr folgen?</h1><div class=\"k4-split\"><div class=\"k4-visual\"><h3>TalentAI · fiktive Empfehlung</h3><div class=\"k4-bar\"><span>Thomas</span><div><i style=\"width:91%\"></i></div><b>91</b></div><div class=\"k4-bar\"><span>Daniel</span><div><i style=\"width:83%\"></i></div><b>83</b></div><div class=\"k4-bar\"><span>Miriam</span><div><i style=\"width:68%\"></i></div><b>68</b></div><div class=\"k4-bar\"><span>Sarah</span><div><i style=\"width:62%\"></i></div><b>62</b></div><small>Fiktive Planspielwerte – keine Forschungsdaten</small></div><div class=\"k4-stack\"><article class=\"k4-panel \"><h3>Modellmerkmale</h3><p>Durchgehende Vollzeit, Führungsvertretungen, persönliche Empfehlungen, Karrieregeschwindigkeit, Sichtbarkeit im Topmanagement.</p></article><article class=\"k4-panel \"><h3>Aufgabe 1</h3><p>Welche Merkmale messen relevante Führungskompetenz? Welche könnten historische Vorteile reproduzieren?</p></article><article class=\"k4-panel \"><h3>Aufgabe 2</h3><p>Würdet ihr die KI-Rangliste übernehmen, verändern oder verwerfen? Begründet mit drei Argumenten.</p></article><article class=\"k4-panel \"><h3>Wichtig</h3><p>Die Zahlen sind bewusst konstruierte Simulationswerte – keine Ergebnisse einer echten KI-Studie.</p></article></div></div></section>"},{"id":"b3k4-game-decision","title":"Planspiel · Faire Entscheidung","html":"<section class=\"scene-inner k4-slide k4-cards\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>PLANSPIEL · RUNDE 4</span></div><h1>Entwickelt ein belastbares Auswahlverfahren</h1><div class=\"k4-twocol\"><article class=\"k4-panel \"><h3>Die Gruppe entscheidet erneut</h3><p>ohne vorgegebene Musterperson.</p></article><article class=\"k4-panel \"><h3>100-Punkte-Gewichtung</h3><p>Führung &amp; Entwicklung · digitale Kompetenzen · Change Management · Kommunikation/Konflikt · strategisches Denken. Gewichtung selbst festlegen.</p></article><article class=\"k4-panel \"><h3>Bewertung</h3><p>Legt pro Kriterium mindestens einen beobachtbaren Beleg fest. Fehlen Belege, benennt den zusätzlichen Prüfbedarf.</p></article><article class=\"k4-panel \"><h3>Drei Regeln</h3><p>Beispielsweise strukturierte Interviews, gleiche Bewertungsskalen, dokumentierte Entscheidungen, Prüfung auf Gruppenunterschiede.</p></article></div><div class=\"k4-bottomnote\">Abgabe: Auswahlentscheidung · 100-Punkte-Gewichtung · drei faire Verfahrensregeln</div></section>"},{"id":"b3k4-debrief","title":"Planspiel · Auswertung","html":"<section class=\"scene-inner k4-slide k4-cards\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>TRANSFER</span></div><h1>Keine Musterperson – aber bessere Entscheidungen</h1><div class=\"k4-quote\">Bewertet die Qualität eurer Begründung, nicht ob ihr eine erwartete Person ausgewählt habt.</div><div class=\"k4-twocol\"><article class=\"k4-panel \"><h3>Reflexion 1</h3><p>Welche Entscheidung änderte sich durch zusätzliche Informationen?</p></article><article class=\"k4-panel \"><h3>Reflexion 2</h3><p>Hat der KI-Score eure Bewertung beeinflusst – trotz offengelegter Verzerrungsrisiken?</p></article><article class=\"k4-panel \"><h3>Reflexion 3</h3><p>Wo treffen sich Skills-based Hiring, Generationenstereotype und New Leadership?</p></article><article class=\"k4-panel \"><h3>Take-away</h3><p>Fairness ist ein überprüfbares Organisationsdesign, kein Bauchgefühl.</p></article></div></section>"},{"id":"b3c4-system","title":"Kapitel 4 · Management-Fazit","html":"<section class=\"scene-inner k4-slide k4-cards\"><div class=\"k4-top\"><span>BLOCK 3 · KAPITEL 4</span><span>TRANSFER</span></div><h1>Nicht Menschen reparieren – Systeme prüfen</h1><div class=\"k4-quote\">Wer Führung verändern will, muss Zugang, Bewertung und Beförderung verändern.</div><div class=\"k4-twocol\"><article class=\"k4-panel \"><h3>Diagnose</h3><p>Wo in der Karrierepipeline entstehen Unterschiede?</p></article><article class=\"k4-panel \"><h3>Intervention</h3><p>Welche strukturellen Barrieren lassen sich tatsächlich ändern?</p></article><article class=\"k4-panel \"><h3>Kontrolle</h3><p>Woran erkennen wir, ob Maßnahmen wirken?</p></article><article class=\"k4-panel \"><h3>Transfer</h3><p>Nehmt eure drei Regeln aus dem Planspiel mit in Kapitel 5: Organisationen verändern.</p></article></div></section>"},{"id":"b3c5-start","title":"Organisationen wirklich verändern","html":"<section class=\"scene-inner b3-scene chapter-cover\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 5</div><h1>Organisationen wirklich verändern</h1><div class=\"b3-layout\"><div><p class=\"lead\">Eine gute Idee verändert noch keine Organisation. Aus Diagnose muss eine lernende Intervention werden.</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/change_loop.svg\" alt=\"Diagnose → Pilot → Messen → Lernen\"><figcaption>Diagnose → Pilot → Messen → Lernen</figcaption></figure></div></section>"},{"id":"b3c5-loop","title":"Pilotieren statt Big Bang","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 5 · CHANGE LOGIK</div><h1>Pilotieren statt Big Bang</h1><div class=\"b3-layout\"><div><p><strong>Problem diagnostizieren → Intervention begrenzen → Wirkung messen → anpassen oder skalieren.</strong></p><p class=\"callout\">Didaktische Synthese aus dem Modul – kein einzelnes universelles Change-Modell.</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/change_loop.svg\" alt=\"Veränderung als überprüfbare Lernschleife\"><figcaption>Veränderung als überprüfbare Lernschleife</figcaption></figure></div></section>"},{"id":"b3c5-crisis","title":"Save the Transformation","html":"<section class=\"scene-inner b3-scene mission\"><div class=\"eyebrow\">MISSION 17 · 30 MIN</div><h1>Save the Transformation</h1><div class=\"b3-layout\"><div><p>NovaWorks hat vieles aus Block 1 und 2 eingeführt – trotzdem kippt die Transformation.</p><div class=\"stack-cards\"><b>Fluktuation steigt</b><b>Führungskräfte blockieren</b><b>Teams überfordert</b><b>Kunden sehen keinen Mehrwert</b><b>Skill Gaps bleiben</b></div><p>Budget reicht für <strong>drei Interventionen</strong>. Priorisiert und definiert je eine Erfolgskennzahl.</p></div></div></section>"},{"id":"b3c5-redteam","title":"Red Team","html":"<section class=\"scene-inner b3-scene challenge\"><div class=\"eyebrow\">KAPITEL 5 · 10 MIN</div><h1>Red Team</h1><div class=\"b3-layout\"><div><ol><li>Welche Annahme ist am schwächsten?</li><li>Wer könnte verlieren?</li><li>Welche Nebenwirkung droht?</li><li>Was müsste nach vier Wochen messbar sein?</li></ol></div></div></section>"},{"id":"b3c6-start","title":"YOUR FUTURE","html":"<section class=\"scene-inner b3-scene chapter-cover\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 6</div><h1>YOUR FUTURE</h1><div class=\"b3-layout\"><div><p class=\"lead\">NovaWorks ist vorbei. Jetzt geht es um euch: Wie positioniert ihr euch in einem Arbeitsmarkt, in dem Abschluss, Skills, KI und Praxiserfahrung gleichzeitig zählen?</p></div><figure class=\"b3-visual\"><img src=\"assets/block3/career_blueprint.svg\" alt=\"My Future of Work Blueprint\"><figcaption>My Future of Work Blueprint</figcaption></figure></div></section>"},{"id":"b3c6-market","title":"Der Berufseinstieg ist anspruchsvoller geworden","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 6 · DEUTSCHLAND 2025</div><h1>Der Berufseinstieg ist anspruchsvoller geworden</h1><div class=\"b3-layout\"><div><p>Die Bundesagentur für Arbeit berichtet 2025 eine Akademiker-Arbeitslosenquote von <strong>3,3 %</strong>. Gleichzeitig stieg die sozialversicherungspflichtige Beschäftigung von Akademiker:innen weiter.</p><p>Die BA weist darauf hin, dass Berufseinsteiger bei schwächerer Nachfrage besonders betroffen sind, weil Arbeitgeber häufig Berufserfahrung bevorzugen und KI Teile klassischer Einstiegsaufgaben übernehmen kann.</p><div class=\"source-note\">Bundesagentur für Arbeit · Blickpunkt Arbeitsmarkt Akademiker:innen, Stand Februar 2026 · <a href=\"https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Themen-im-Fokus/Berufe/Akademikerinnen/Allgemeiner-Teil-Nav.html\" target=\"_blank\" rel=\"noopener\">Quelle öffnen ↗</a></div></div></div></section>"},{"id":"b3c6-whatmatters","title":"Was macht euch schwer austauschbar?","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 6 · POSITIONIERUNG</div><h1>Was macht euch schwer austauschbar?</h1><div class=\"b3-layout\"><div><div class=\"four-cols\"><b>FACHWISSEN</b><b>KI-KOMPETENZ</b><b>PROBLEMLÖSEN</b><b>KOMMUNIKATION</b></div><p>Dazu kommt: schnell weiterlernen und Ergebnisse sichtbar machen.</p><p class=\"callout\">Nicht „Ich kann ChatGPT“, sondern: <strong>Welches Problem löse ich besser – und was kann ich dafür zeigen?</strong></p></div><figure class=\"b3-visual\"><img src=\"assets/block3/skills_stack.svg\" alt=\"Vom Wissen zum sichtbaren Nachweis\"><figcaption>Vom Wissen zum sichtbaren Nachweis</figcaption></figure></div></section>"},{"id":"b3c6-recruiter","title":"Recruiter Test","html":"<section class=\"scene-inner b3-scene challenge\"><div class=\"eyebrow\">KAPITEL 6 · 12 MIN</div><h1>Recruiter Test</h1><div class=\"b3-layout\"><div><p>Drei Absolvent:innen. Gleicher Abschluss. Ähnliche Noten.</p><div class=\"three-cols\"><div><b>A</b><p>Abschluss und Praktika.</p></div><div><b>B</b><p>20 Skills und KI-Tools.</p></div><div><b>C</b><p>2 Projekte: Problem, Vorgehen, KI-Einsatz, Ergebnis.</p></div></div><p><strong>Wen ladet ihr ein – und welche Evidenz fehlt?</strong></p></div></div></section>"},{"id":"b3c6-blueprint","title":"My Future of Work Blueprint","html":"<section class=\"scene-inner b3-scene mission\"><div class=\"eyebrow\">INDIVIDUELL · 25 MIN</div><h1>My Future of Work Blueprint</h1><div class=\"b3-layout\"><div><ol><li><strong>I CAN:</strong> Was kann ich nachweisbar gut?</li><li><strong>I SOLVE:</strong> Welche Probleme kann ich lösen?</li><li><strong>I PROVE:</strong> Welcher Proof of Work zeigt das?</li><li><strong>I LEARN:</strong> Welchen Skill baue ich als Nächstes auf?</li><li><strong>I MOVE:</strong> Welche drei Schritte mache ich in 90 Tagen?</li></ol></div><figure class=\"b3-visual\"><img src=\"assets/block3/career_blueprint.svg\" alt=\"Persönlicher Abschluss des Moduls\"><figcaption>Persönlicher Abschluss des Moduls</figcaption></figure></div></section>"},{"id":"b3c6-marketkit","title":"Career Kit · konkret","html":"<section class=\"scene-inner b3-scene \"><div class=\"eyebrow\">KAPITEL 6 · TAKE-AWAY</div><h1>Career Kit · konkret</h1><div class=\"b3-layout\"><div><div class=\"stack-cards\"><b>CV / LinkedIn: Wirkung statt Aufgabenlisten</b><b>Portfolio: 2–3 echte Arbeitsproben</b><b>KI: Nutzung + Qualitätskontrolle erklären</b><b>Netzwerk: Menschen kennen eure Arbeit</b><b>Interview: Problem → Vorgehen → Ergebnis → Lernen</b></div><p>Der erste Job ist keine endgültige Identität. Er sollte Lernen, relevante Erfahrung und Anschlussfähigkeit ermöglichen.</p></div></div></section>"},{"id":"b3-finale","title":"NovaWorks is over. Now it's about you.","html":"<section class=\"scene-inner b3-scene dark\"><div class=\"eyebrow\">MODUL · FINALE</div><h1>NovaWorks is over. Now it's about you.</h1><div class=\"b3-layout\"><div><p class=\"lead\">Arbeit verändert sich. Organisationen verändern sich. Eure Aufgabe ist nicht, jede Entwicklung vorherzusagen – sondern handlungsfähig zu bleiben.</p><div class=\"chapter-map\"><b>VERSTEHEN</b><b>ENTSCHEIDEN</b><b>GESTALTEN</b><b>LERNEN</b><b>ZEIGEN</b><b>WEITERGEHEN</b></div><div class=\"challenge-output\">EXIT TICKET · Eine Sache, die ich ab morgen anders mache.</div></div><figure class=\"b3-visual\"><img src=\"assets/block3/career_blueprint.svg\" alt=\"Vom Modul in die eigene berufliche Entwicklung\"><figcaption>Vom Modul in die eigene berufliche Entwicklung</figcaption></figure></div></section>"}];

// Block 3 Erweiterung: interaktive, selbsttragende Lehr- und Planspielmaterialien
const b3ExtraScenes=[{"id":"b3x1-bridge","title":"Warum Teamrollen? Warum Belbin?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · ÜBERGANG</div><h1>Fachliche Skills reichen nicht: Wie wird aus Menschen ein Team?</h1><div class=\"b3-layout\"><div><p class=\"lead\">NovaCare braucht nicht nur API-, UX- und Datenschutzwissen. Das Team muss auch Ideen entwickeln, Entscheidungen treffen, Konflikte lösen und Ergebnisse zuverlässig umsetzen.</p><div class=\"b3-panel\"><h3>Warum Teamrollen betrachten?</h3><p>Fachkompetenz beantwortet: <strong>Was kann jemand?</strong> Teamrollen betrachten: <strong>Wie trägt jemand zur Zusammenarbeit bei?</strong> Eine gute Zusammensetzung berücksichtigt beides – ohne Menschen auf Typen festzulegen.</p></div><div class=\"b3-panel\"><h3>Welche Modelle gibt es?</h3><p><strong>Belbin:</strong> neun bevorzugte Beiträge zur Teamarbeit. <strong>DISC:</strong> Verhaltensstile und Kommunikation. <strong>Big Five:</strong> wissenschaftlich breit untersuchte Persönlichkeitsdimensionen. <strong>RACI:</strong> Verantwortlichkeiten im Projekt, kein Persönlichkeitsmodell.</p></div></div><div><div class=\"b3-panel\"><h3>Warum verwenden wir hier Belbin?</h3><p>Belbin ist für unsere Fallstudie anschaulich: Es lenkt den Blick auf <strong>ergänzende Beiträge</strong> wie Ideenfindung, Koordination, Umsetzung und Qualitätssicherung. Damit können die Gruppen ihre NovaCare-Teamaufstellung reflektieren.</p></div><div class=\"b3-panel\"><h3>Wichtige Grenze</h3><p>Teamrollen sind <strong>keine festen Persönlichkeitstypen</strong> und kein Nachweis beruflicher Eignung. Der folgende externe Online-Selbsttest dient der freiwilligen Reflexion und ist <strong>kein offiziell autorisiertes oder nachweislich validiertes Belbin-Verfahren</strong>.</p></div><p><strong>Diskussionsimpuls:</strong> Welche Zusammenarbeit könnte in eurem NovaCare-Team fehlen, obwohl alle fachlichen Skills abgedeckt sind?</p></div></div></section>"},{"id":"b3x1-roles","title":"Neun Belbin-Teamrollen – ein Überblick","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 1 · TEAMROLLEN</div><h1>Neun Belbin-Teamrollen – ein Überblick</h1><div class=\"b3new-photo\"><img src=\"assets/visual/people.jpg\" alt=\"Illustration: Neun Belbin-Teamrollen – ein Überblick\"></div><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>Ideen & Außenwelt</h3><p>Plant (Ideengeber), Resource Investigator (Wegbereiter), Coordinator (Koordinator).</p></article><article><h3>Antrieb & Urteil</h3><p>Shaper (Macher), Monitor Evaluator (Beobachter), Teamworker (Teamarbeiter).</p></article><article><h3>Umsetzung & Expertise</h3><p>Implementer (Umsetzer), Completer Finisher (Perfektionist), Specialist (Spezialist).</p></article></div><p class=\"b3new-note\">Belbin ist ein Modell bevorzugter Beiträge zur Teamarbeit, kein Test für fachliche Eignung. Das offizielle Belbin-Verfahren ist geschützt und berücksichtigt auch Fremdeinschätzungen. Der verlinkte Online-Selbsttest dient nur der Reflexion und ist nicht das offizielle Belbin-Verfahren.</p></div></section>"},{"id":"b3x1-test","title":"Online-Selbsttest: Teamrollen reflektieren","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 1 · TEAMROLLEN</div><h1>Welche Teamrollen passen zu mir?</h1><div class=\"b3new-body\"><p class=\"lead\">Erkunde deine bevorzugten Teambeiträge mit einem externen Online-Selbsttest zu den neun Belbin-Teamrollen.</p><div class=\"b3new-cards\"><article><h3>1 · Test öffnen</h3><p>Öffne den Online-Test in einem neuen Tab und beantworte die Fragen für dich persönlich.</p><p><a href=\"https://nikku.github.io/belbin/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"b3new-action\">Online-Selbsttest starten ↗</a></p><p><small>https://nikku.github.io/belbin/</small></p></article><article><h3>2 · Profil reflektieren</h3><p>Notiere deine zwei am stärksten ausgeprägten Teamrollen und eine Rolle mit geringerem Wert. Was überrascht dich?</p></article><article><h3>3 · Im Team übertragen</h3><p>Welche Beiträge sind in eurer NovaWorks-Gruppe vertreten? Was fehlt möglicherweise für eine gute Zusammenarbeit?</p></article></div><p class=\"b3new-note\"><strong>Einordnung:</strong> Dies ist ein frei zugänglicher, nicht offiziell autorisierter Belbin-Online-Test. Eine wissenschaftliche Validierung dieser Umsetzung ist nicht belegt. Ergebnisse dienen ausschließlich der freiwilligen Selbstreflexion, nicht der Eignungsdiagnostik. Niemand muss persönliche Ergebnisse offenlegen.</p></div></section>"},{"id":"b3x1-skills","title":"Teamrollen ≠ Fachkompetenzen","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 1 · TRANSFER</div><h1>Teamrollen ≠ Fachkompetenzen</h1><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>Fachliche Skills</h3><p>Python, UX, Datenschutz, Kundenservice, Schnittstellenentwicklung.</p></article><article><h3>Teambeiträge</h3><p>Ideen einbringen, strukturieren, kritisch prüfen, vermitteln, umsetzen.</p></article><article><h3>Konsequenz</h3><p>Ein fachlich starkes Team kann an Abstimmung scheitern; ein harmonisches Team kann entscheidende technische Skills vermissen lassen.</p></article></div><p><strong>Reflexion:</strong> Welche Teambeiträge vermutet ihr in eurer Gruppe? Welche müsst ihr bewusst organisieren?</p></div></section>"},{"id":"b3x2-history","title":"Boomer, X, Y, Z und Alpha","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 2 · GENERATIONEN</div><h1>Boomer, X, Y, Z und Alpha</h1><div class=\"b3new-photo\"><img src=\"assets/visual/people.jpg\" alt=\"Illustration: Boomer, X, Y, Z und Alpha\"></div><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>Babyboomer · ca. 1946–1964</h3><p>Aufwachsen in Nachkriegszeit und wirtschaftlichem Wandel.</p></article><article><h3>Generation X · ca. 1965–1980</h3><p>Analoge Kindheit, zunehmende Digitalisierung im Berufsleben.</p></article><article><h3>Generation Y · ca. 1981–1996</h3><p>Internet und Globalisierung prägen Ausbildungs- und Berufseinstieg.</p></article><article><h3>Generation Z · ca. 1997–2012</h3><p>Smartphones und soziale Medien früh im Alltag; unterschiedliche Krisenerfahrungen.</p></article><article><h3>Generation Alpha · ab ca. 2013</h3><p>Noch überwiegend nicht im regulären Arbeitsmarkt.</p></article></div><p class=\"b3new-note\">Jahresgrenzen variieren je nach Quelle. Kohorten sind keine Persönlichkeitstypen.</p></div></section>"},{"id":"b3x2-briefing","title":"Generation Clash: Euer Arbeitsauftrag","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · PLANSPIEL · BRIEFING</div><h1>Generation Clash: Rettet die Zusammenarbeit</h1><p class=\"lead\">NovaCare ist sechs Wochen in Verzug. Kunden melden Fehler; KI-Vorschläge werden nicht zuverlässig kontrolliert. Ihr seid ein internes Beratungsteam und sollt die Zusammenarbeit stabilisieren – ohne vorschnell Altersgruppen verantwortlich zu machen.</p><div class=\"b3-card-grid\"><div class=\"b3-card\"><h3>1 · Diagnose (8 Min.)</h3><p>Lest die vier Personenprofile ohne Altersangaben. Findet drei konkrete Konfliktursachen und belegt sie mit Aussagen aus den Profilen.</p></div><div class=\"b3-card\"><h3>2 · Teamregeln (10 Min.)</h3><p>Entwickelt drei überprüfbare Regeln: Wer gibt KI-Vorschläge frei? Wie werden Entscheidungen dokumentiert? Wann stimmt sich das Team ab?</p></div><div class=\"b3-card\"><h3>3 · Wissenstransfer (7 Min.)</h3><p>Plant einen Austausch zwischen Thomas und Mia: Wer vermittelt wem was? Wie überprüft ihr nach vier Wochen den Lernerfolg?</p></div><div class=\"b3-card\"><h3>4 · Reflexion (5 Min.)</h3><p>Deckt erst jetzt das Alter auf. Hat es eure Diagnose verändert? Präsentiert eure Lösung in 90 Sekunden.</p></div></div><p class=\"callout\"><b>Abgabe:</b> 3 Konfliktursachen + 3 konkrete Teamregeln + 1 Wissenstransferplan + 1 Satz zur Rolle von Altersstereotypen.</p></section>"},{"id":"b3x2-cases","title":"Generation Clash: Die vier Personen","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 2 · PLANSPIEL · ROLLEN</div><h1>Generation Clash: Die vier Personen</h1><div class=\"b3new-photo\"><img src=\"assets/visual/meeting.jpg\" alt=\"Illustration: Generation Clash: Die vier Personen\"></div><div class=\"b3new-body\"><p>NovaCare ist sechs Wochen im Verzug. Kunden melden Fehler; KI-Vorschläge werden nicht konsequent geprüft. Die Aussagen unten sind zunächst <strong>ohne Alter</strong> zu beurteilen.</p><div class=\"b3new-cards\"><article><h3>Thomas · Senior Engineer</h3><p>Qualität und Erfahrungswissen sichern; Sorge vor ungeprüfter KI-Automation.</p></article><article><h3>Sabine · Projektleitung</h3><p>Verlässliche Termine, klare Zuständigkeiten, Spielraum für flexible Arbeit.</p></article><article><h3>Daniel · Softwareentwicklung</h3><p>Kurze Abstimmungswege, Autonomie, überprüfbare Ergebnisse.</p></article><article><h3>Mia · Junior Data Analyst</h3><p>KI-Tools ausprobieren, fachliche Rückmeldung, Produktwissen lernen.</p></article></div><details><summary>Alter erst nach der ersten Analyse aufdecken</summary><p>Thomas 63 (Babyboomer), Sabine 47 (Generation X), Daniel 34 (Generation Y), Mia 24 (Generation Z). Alter erklärt nicht automatisch die geschilderten Verhaltensweisen.</p></details></div></section>"},{"id":"b3x2-gameplus","title":"Generation Clash: Ergebnis und Auswertung","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 2 · PLANSPIEL · AUSWERTUNG</div><h1>Welche Lösung ist wirklich generationengerecht?</h1><p class=\"lead\">Vergleicht eure Ergebnisse mit diesen Kriterien.</p><div class=\"b3-card-grid\"><div class=\"b3-card\"><h3>Konfliktursachen</h3><p>Wurden konkrete Arbeitsabläufe, Verantwortlichkeiten und Qualitätsprobleme benannt – statt Altersgruppen?</p></div><div class=\"b3-card\"><h3>Teamregeln</h3><p>Sind Freigabe, Dokumentation und Abstimmung eindeutig geregelt und überprüfbar?</p></div><div class=\"b3-card\"><h3>Wissenstransfer</h3><p>Lernen beide Seiten voneinander? Gibt es nach vier Wochen einen beobachtbaren Fortschritt?</p></div></div><p class=\"callout\"><b>Transfer:</b> Unterschiedliche Erwartungen im Team sind real. Ob sie durch Generation, Lebensphase, Aufgaben oder Arbeitsbedingungen entstehen, muss erst untersucht werden.</p></section>"},{"id":"b3x3-pressure","title":"Mittleres Management unter Druck","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 3 · ORGANISATIONSENTWICKLUNG</div><h1>Mittleres Management: Was verschwindet, was bleibt?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Nicht „KI ersetzt Chefs“, sondern: <strong>Managementaufgaben werden auf Technik, Teams und Führungskräfte neu verteilt.</strong></p><div class=\"compare\"><div><h3>Weniger Vermittlungsarbeit</h3><p>Berichte bündeln, Informationen weiterleiten, Routinefreigaben koordinieren.</p></div><div><h3>Mehr echte Führungsarbeit</h3><p>Menschen entwickeln, schwierige Konflikte lösen, Risiken abwägen, Ergebnisse verantworten.</p></div></div><p class=\"callout\">Gartner berichtet 2026 über Pläne zum Abbau von Hierarchieebenen, warnt aber zugleich vor dem Verlust notwendiger Führungsfunktionen. <a href=\"https://www.gartner.com/en/documents/7658761\" target=\"_blank\" rel=\"noopener\">Gartner 2026 ↗</a></p></div></div></section>"},{"id":"b3x3-est","title":"Schätzfragen: Wie stark wirkt Führung?","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 3 · EINSTIEG · 7 MIN</div><h1>Schätzt zuerst: Wie verändert sich Führung?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Stimmt zunächst ab. Danach öffnet ihr die Antworten. Achtet darauf, ob eine Zahl eine Beobachtung, eine Befragung oder eine Prognose beschreibt.</p><details><summary><strong>1 · Welchen Anteil der Unterschiede im Team-Engagement bringt Gallup mit der Führungskraft in Verbindung?</strong></summary><p><strong>Rund 70 % der Varianz zwischen Teams. Kein Anteil an der Leistung einzelner Menschen.</strong> <a href=\"https://www.gallup.com/workplace/395210/engage-frontline-managers.aspx\" target=\"_blank\" rel=\"noopener\">Quelle ↗</a></p><p class=\"source-note\">Gallup; Analyse des Mitarbeiterengagements</p></details><details><summary><strong>2 · Wie viele Organisationen könnten laut Gartner bis 2026 durch KI mehr als die Hälfte ihrer mittleren Managementstellen streichen?</strong></summary><p><strong>Prognose: 20 % der Organisationen. Keine nachgewiesene Abbauquote.</strong> <a href=\"https://www.deloitte.com/us/en/insights/topics/talent/human-capital-trends/2025/future-of-the-middle-manager.html\" target=\"_blank\" rel=\"noopener\">Quelle ↗</a></p><p class=\"source-note\">Gartner-Prognose, referenziert von Deloitte 2025</p></details><details><summary><strong>3 · Wie viele KI-nutzende Organisationen meldeten 2026 rückblickend einen KI-bedingten Rückgang ihrer gesamten Belegschaft?</strong></summary><p><strong>14 %. Nicht speziell Führungskräfte; Selbstauskunft von Befragten.</strong> <a href=\"https://www.mckinsey.com/capabilities/quantumblack/our-insights/the-state-of-ai\" target=\"_blank\" rel=\"noopener\">Quelle ↗</a></p><p class=\"source-note\">McKinsey State of AI 2026</p></details><details><summary><strong>4 · Wie viele dieser Organisationen erwarten im nächsten Jahr einen KI-bedingten Personalrückgang?</strong></summary><p><strong>39 %. Erwartung, keine bereits realisierte Kürzung.</strong> <a href=\"https://www.mckinsey.com/capabilities/quantumblack/our-insights/the-state-of-ai\" target=\"_blank\" rel=\"noopener\">Quelle ↗</a></p><p class=\"source-note\">McKinsey State of AI 2026</p></details><details><summary><strong>5 · Wie viele befragte Führungskräfte fanden, dass KI ihre Erwartungen an die Verbesserung der Teamarbeit erfüllt hat?</strong></summary><p><strong>45 %. Wahrnehmung der Befragten, keine objektive Leistungsquote.</strong> <a href=\"https://www.gartner.com/en/newsroom/press-releases/2026-3-4-gartner-hr-survey-reveals-45-percent-of-managers-report-ai-has-lived-up-to-their-expectations\" target=\"_blank\" rel=\"noopener\">Quelle ↗</a></p><p class=\"source-note\">Gartner HR Survey, März 2026</p></details><p class=\"callout\"><strong>Leitfrage:</strong> Weniger Hierarchie – aber wer übernimmt Coaching, Qualitätssicherung und Verantwortung?</p></div></div></section>"},{"id":"b3x3-ai","title":"Führung im KI-Zeitalter","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">KAPITEL 3 · ORGANISATION IM KI-ZEITALTER</div><h1>Weniger Manager durch KI – funktioniert das?</h1><div class=\"b3-layout\"><div><p class=\"lead\">Unternehmen wollen Routinearbeit automatisieren und Entscheidungsebenen reduzieren. Doch Prognosen sind keine nachgewiesenen Stellenstreichungen.</p><div class=\"compare\"><div><div class=\"big-stat\">20 %</div><h3>Prognose bis 2026</h3><p>Gartner erwartete, dass 20 % der Organisationen KI nutzen könnten, um ihre Strukturen abzuflachen und mehr als die Hälfte der mittleren Managementpositionen zu streichen.</p></div><div><div class=\"big-stat\">14 %</div><h3>Beobachtung 2026</h3><p>Bei McKinsey berichteten 14 % der KI-nutzenden Organisationen einen KI-bedingten Rückgang der Gesamtbelegschaft im vergangenen Jahr. Das ist keine gesonderte Managerquote.</p></div></div><h3>Wie soll das laut Unternehmen funktionieren?</h3><div class=\"compare\"><div><h3>KI übernimmt Routine</h3><p>Statusberichte, Datenaufbereitung, Informationssuche und Monitoring. Kleine Teams entscheiden selbstständiger; weniger Eskalationsstufen.</p></div><div><h3>Führung wird neu verteilt</h3><p>Führungskräfte sollen mehr coachen, Prioritäten klären und Verantwortung sichern. Das setzt klare Entscheidungsrechte, Kompetenzaufbau und menschliche Kontrolle voraus.</p></div></div><p class=\"callout\"><strong>Diskussion:</strong> Was passiert mit Feedback, Nachwuchsentwicklung und Fehlerverantwortung, wenn Führungsebenen entfallen?</p><div class=\"source-note\">Quellen: <a href=\"https://www.deloitte.com/us/en/insights/topics/talent/human-capital-trends/2025/future-of-the-middle-manager.html\" target=\"_blank\" rel=\"noopener\">Deloitte/Gartner-Prognose ↗</a> · <a href=\"https://www.mckinsey.com/capabilities/quantumblack/our-insights/the-state-of-ai\" target=\"_blank\" rel=\"noopener\">McKinsey 2026 ↗</a> · <a href=\"https://www.gartner.com/en/articles/ai-shaped-organization\" target=\"_blank\" rel=\"noopener\">Gartner: KI-geprägte Organisation ↗</a></div></div></div></section>"},{"id":"b3x5-forms","title":"Organisationsformen: Die Grundlagen","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">KAPITEL 5 · ORGANISATIONSDESIGN</div><h1>Welche Organisationsform löst welches Problem?</h1><p class=\"lead\">Keine Struktur ist immer die beste. Entscheidend sind Koordination, Verantwortlichkeit und Anpassungsfähigkeit.</p><div class=\"b3new-cards\"><article><h3>Einlinien- & Stablinienorganisation</h3><p>Eine disziplinarische Weisungslinie; Stäbe beraten. <b>Plus:</b> klare Verantwortung. <b>Risiko:</b> lange Entscheidungswege.</p></article><article><h3>Funktionale Organisation</h3><p>Entwicklung, Produktion, Vertrieb etc. <b>Plus:</b> Expertise. <b>Risiko:</b> Silos und Übergaben.</p></article><article><h3>Spartenorganisation</h3><p>Eigenständige Produkt- oder Kundensegmente. <b>Plus:</b> Marktnähe. <b>Risiko:</b> doppelte Ressourcen.</p></article><article><h3>Matrixorganisation</h3><p>Funktion und Produkt/Projekt überlagern sich. <b>Plus:</b> Kooperation. <b>Risiko:</b> konkurrierende Prioritäten.</p></article><article><h3>Agile Produktteams / Netzwerk</h3><p>Interdisziplinäre Teams mit dezentralen Entscheidungen. <b>Plus:</b> Tempo. <b>Risiko:</b> ungeklärte Verantwortung.</p></article><article><h3>Merksatz</h3><p><b>Linie</b> beschreibt Weisungswege, <b>funktional / divisional</b> das Gliederungsprinzip, <b>Matrix</b> die Überlagerung. Modelle lassen sich kombinieren.</p></article></div></section>"},{"id":"b3x5-chart","title":"Wie sieht das Organigramm aus?","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 5 · IST-ORGANISATION</div><h1>Wie sieht das Organigramm aus?</h1><div class=\"b3new-body\"><div class=\"b3new-org\"><div class=\"b3new-org-top\">Geschäftsführung</div><div class=\"b3new-org-grid\"><div>Entwicklung<br><small>70 MA</small></div><div>Produktion<br><small>90 MA</small></div><div>Vertrieb & Service<br><small>45 MA</small></div><div>IT & Daten<br><small>20 MA</small></div><div>HR & Finanzen<br><small>15 MA</small></div></div></div><p><strong>Ist-Struktur NovaWorks:</strong> 240 Beschäftigte; funktionale Gliederung, vier Hierarchieebenen (Geschäftsführung → Bereichsleitung → Teamleitung → Mitarbeitende). 1 Geschäftsführung, 5 Bereichsleitungen, 18 Teamleitungen, 216 Mitarbeitende. Diese fiktiven Werte sind die verbindliche Ausgangslage des Planspiels.</p><div class=\"b3new-cards\"><article><h3>Aktuelle Probleme</h3><p>Freigaben über 3 Ebenen; durchschnittlich 14 Tage für bereichsübergreifende Änderungen; doppelte Statusberichte; NovaCare-Pilot verspätet.</p></article><article><h3>Auftrag der Geschäftsführung</h3><p>In 6 Monaten schnellere Entscheidungen und 20 % weniger Managementkosten; Beschäftigtenzahl zunächst konstant. Die Ziele sind fiktive Simulationsannahmen.</p></article><article><h3>Mitbestimmung</h3><p>Der Betriebsrat ist frühzeitig einzubeziehen. Personalmaßnahmen und KI-Einsatz müssen rechtlich geprüft werden; keine automatische Kündigungsannahme.</p></article></div></div></section>"},{"id":"b3x5-est","title":"Schätzfrage: Bayer als Realitätstest","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 5 · SCHÄTZAUFGABE</div><h1>Schätzfrage: Bayer als Realitätstest</h1><div class=\"b3new-body\"><div class=\"b3new-quiz\"><p class=\"b3new-q\">Um wie viel Prozent hat Bayer nach eigenen Angaben seine Managementpositionen im Zuge der DSO-Transformation bis März 2026 reduziert?</p><button type=\"button\" class=\"b3new-reveal\" data-target=\"b3ans6\">Lösung aufdecken</button><div class=\"b3new-answer\" id=\"b3ans6\" hidden><strong>Rund 67 %</strong><p>Bayer berichtet zudem von etwa halbierten Hierarchieebenen. Die Transformation ist nicht ausschließlich durch KI motiviert. Unternehmensangabe, keine unabhängige Kausalstudie.</p><small>Quelle: Bayer, Unternehmensmitteilungen 2026, bayer.com</small></div></div></div></section>"},{"id":"b3x5-bayer","title":"Bayer: Dynamic Shared Ownership","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 5 · PRAXISFALL</div><h1>Bayer: Dynamic Shared Ownership</h1><div class=\"b3new-photo\"><img src=\"assets/visual/meeting.jpg\" alt=\"Illustration: Bayer: Dynamic Shared Ownership\"></div><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>Warum?</h3><p>Weniger Bürokratie, schnellere Entscheidungen, stärkerer Kundenfokus.</p></article><article><h3>Wie?</h3><p>Kleinere eigenverantwortliche Teams, neue Führungsrollen und kürzere Planungszyklen.</p></article><article><h3>Welche Risiken?</h3><p>Koordinationskosten, unklare Zuständigkeiten, Veränderungsbelastung, Sicherung von Expertise.</p></article></div><p><strong>Filmimpuls:</strong> <a href=\"https://www.youtube.com/watch?v=_mubMfgrdIQ\" target=\"_blank\" rel=\"noopener\">Offizielles Bayer-Webinar zu DSO (YouTube)</a>. Für die Vorlesung einen 3–5-Minuten-Ausschnitt vorab auswählen; Länge und Ausschnitt sind nicht vorgeprüft.</p><p><strong>Alternative:</strong> <a href=\"https://www.corporate-rebels.com/blog/recording-bayer-event\" target=\"_blank\" rel=\"noopener\">Corporate Rebels: Bayer Self-Management</a>.</p></div></section>"},{"id":"b3x5-design","title":"Mission: Reinvent NovaWorks","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 5 · PLANSPIEL</div><h1>Mission: Reinvent NovaWorks</h1><div class=\"b3new-body\"><div class=\"b3new-task\"><h2>45 Minuten · Teams zu 4–5 Personen</h2><ol><li>Analysiert die Ist-Struktur: fünf Bereiche, 18 Teamleitungen, vier Ebenen und 240 Beschäftigte. Wo entstehen Silos, Wartezeiten und Doppelarbeit?</li><li>Entwerft ein neues Organigramm. Ihr dürft Linie, Matrix, Sparten, Produktteams oder einen Hybrid wählen.</li><li>Definiert Anzahl der Führungsebenen, Führungspositionen und Führungsspannen. Zeigt, wer fachlich und disziplinarisch entscheidet.</li><li>Ordnet KI-Unterstützung zu: Reporting, Planung, Wissensmanagement. Legt menschliche Freigaben fest.</li><li>Beschreibt Betriebsratsbeteiligung, Übergang für betroffene Führungskräfte und zwei messbare Erfolgskennzahlen.</li><li>Erstellt eine 2-Minuten-Managementpräsentation: Vorher → Nachher → Nutzen → Risiken.</li></ol><p><strong>Verbindliche Rahmenbedingungen:</strong> 240 Beschäftigte bleiben in der Simulation zunächst erhalten. Ziel: maximal 3 Hierarchieebenen und maximal 15 formale Führungspositionen (inkl. Geschäftsführung). Kein Team ohne klar verantwortliche Ansprechperson. Es gibt keine einzig richtige Struktur.</p></div><details><summary>Beispiel einer vertretbaren Lösung (erst nach der Bearbeitung)</summary><p>Geschäftsführung → 4 Produkt-/Plattformbereiche → 10 Teamleads, zusammen 15 Führungspositionen. Service und IT arbeiten funktionsübergreifend; Fachstandards werden über Communities of Practice gesichert. Risiken: Überlastung, uneindeutige fachliche Zuständigkeiten, Qualifizierungsbedarf.</p></details></div></section>"},{"id":"b3x5-event","title":"Ereigniskarte: Euer Umbau gerät unter Druck","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 5 · PLANSPIEL · TWIST</div><h1>Ereigniskarte: Euer Umbau gerät unter Druck</h1><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>Betriebsrat</h3><p>Fordert nachvollziehbare Auswahlkriterien, Qualifizierungsangebote und Mitbestimmung bei relevanten Änderungen.</p></article><article><h3>Kunde</h3><p>Eine wichtige Reklamation bleibt zwischen zwei neuen Teams liegen.</p></article><article><h3>Führungskräfte</h3><p>Drei bisherige Teamleitungen befürchten einen Status- und Karriereverlust.</p></article></div><div class=\"b3new-task\"><h2>5 Minuten Nachsteuerung</h2><ol><li>Legt fest, wer den Kundenfall entscheidet.</li><li>Nennt zwei konkrete Maßnahmen für die betroffenen Führungskräfte.</li><li>Ändert gegebenenfalls eine Schnittstelle im Organigramm.</li></ol></div></div></section>"},{"id":"b3x6-goal","title":"Career Cockpit: Deine Zielrolle","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · KARRIERE-WORKSHOP</div><h1>Career Cockpit: Deine Zielrolle</h1><div class=\"b3new-photo\"><img src=\"assets/visual/people.jpg\" alt=\"Illustration: Career Cockpit: Deine Zielrolle\"></div><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>1 · Ziel</h3><p>Wähle zwei realistische Einstiegsrollen und eine Wunschbranche.</p></article><article><h3>2 · Evidenz</h3><p>Was kannst du bereits nachweisen – mit Projekt, Ergebnis, Portfolio oder Zertifikat?</p></article><article><h3>3 · Lücke</h3><p>Welche Kompetenzen fehlen? Was lässt sich in 90 Tagen verbessern?</p></article></div><p><strong>Wichtig:</strong> Online-Selbsttest aus Kapitel 1 nur als Reflexion nutzen, nicht als Eignungssiegel.</p></div></section>"},{"id":"b3x6-cockpit","title":"Dein persönliches Bewerbungscockpit","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · INTERAKTIVES TOOL</div><h1>Dein persönliches Bewerbungscockpit</h1><div class=\"b3new-body\"><p class=\"lead\">Trage deine Ziele, Skills und nächste Schritte ein. Du kannst dein Ergebnis als Textdatei exportieren. Es wird nichts an einen Server gesendet.</p><div id=\"b3-career-cockpit\"></div><p class=\"b3new-note\">Die Eingaben werden nicht automatisch dauerhaft gespeichert. Exportiere dein Ergebnis, bevor du die Lernwelt schließt.</p></div></section>"},{"id":"b3x6-cv","title":"CV-Check: Was Recruiter sehen","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · LEBENSLAUF</div><h1>CV-Check: Was Recruiter sehen</h1><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>Klarer Fokus</h3><p>Position und relevante Erfahrung innerhalb weniger Sekunden erkennbar.</p></article><article><h3>Nachweise statt Floskeln</h3><p>„Projekt mit 5 Personen koordiniert“ statt „teamfähig“.</p></article><article><h3>Lesbarkeit</h3><p>Einheitliche Daten, klare Abschnitte, passende Länge, keine erfundenen Kompetenzen.</p></article><article><h3>KI sinnvoll nutzen</h3><p>Sprachliche Verbesserung und Stellenabgleich – Fakten selbst prüfen, persönliche Daten schützen.</p></article></div><p><strong>Mini-Aufgabe:</strong> Formuliere drei belegbare Bulletpoints aus Studium, Job oder Ehrenamt nach „Tätigkeit → Ergebnis → Wirkung“.</p></div></section>"},{"id":"b3x6-job","title":"Job-Matching: Eine Stellenanzeige zerlegen","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · JOB-MATCHING</div><h1>Job-Matching: Eine Stellenanzeige zerlegen</h1><div class=\"b3new-body\"><div class=\"b3new-task\"><h2>15 Minuten · individuell</h2><ol><li>Suche eine reale, passende Stellenanzeige oder verwende die Musterstelle unten.</li><li>Markiere Muss-Kriterien, Kann-Kriterien und Aufgaben.</li><li>Bewerte für fünf Kriterien deine Nachweise: vorhanden / teilweise / fehlt.</li><li>Wähle die zwei wichtigsten Lücken und plane eine konkrete Lernaktivität.</li></ol><p><strong>Musterstelle NovaWorks – Junior Digital Product Manager (m/w/d):</strong> Anforderungen: Projektarbeit, Datenverständnis, Kundenorientierung, Kommunikation, KI-Grundverständnis; Aufgaben: Anforderungen priorisieren, Kundenfeedback auswerten, Pilot koordinieren. Kann: SQL, agile Methoden.</p></div></div></section>"},{"id":"b3x6-recruiter","title":"Beat the Recruiter: Vier Lebensläufe","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · PLANSPIEL</div><h1>Beat the Recruiter: Vier Lebensläufe</h1><div class=\"b3new-body\"><div class=\"b3new-cards\"><article><h3>A · Marie</h3><p>BWL-Abschluss, 2 Praktika; nennt „kommunikativ“, ohne Beispiele. Keine Datenprojekte.</p></article><article><h3>B · Ben</h3><p>Wirtschaftsinformatik, Hochschulprojekt mit 30 Nutzerinterviews, Dashboard-Prototyp, 6-monatiges Praktikum.</p></article><article><h3>C · Fatima</h3><p>Quereinstieg aus Service, 3 Jahre Kundenkontakt, dokumentierte Prozessverbesserung um 15 %, Onlinekurs SQL.</p></article><article><h3>D · Leon</h3><p>Sehr gute Noten, zahlreiche Tools aufgelistet, aber kaum Projekte oder nachvollziehbare Resultate.</p></article></div><div class=\"b3new-task\"><h2>20 Minuten · Recruiter-Team</h2><ol><li>Lest die Musterstelle auf der vorherigen Folie.</li><li>Wählt zwei Personen für ein Gespräch und begründet die Auswahl anhand konkreter Nachweise.</li><li>Welche Rückfragen würdet ihr stellen?</li><li>Prüft, ob ihr Prestige, Lücken oder unbewiesene Behauptungen zu stark bewertet habt.</li></ol></div><details><summary>Diskussionsimpuls</summary><p>B und C bieten unterschiedliche, gut belegte Stärken. Andere Entscheidungen sind vertretbar, sofern Kriterien transparent und jobbezogen sind.</p></details></div></section>"},{"id":"b3x6-est","title":"Schätzfrage: Wandel bis 2030","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · SCHÄTZAUFGABE</div><h1>Schätzfrage: Wandel bis 2030</h1><div class=\"b3new-body\"><div class=\"b3new-quiz\"><p class=\"b3new-q\">Wie viele der aktuellen Kernkompetenzen könnten sich laut WEF bis 2030 verändern?</p><button type=\"button\" class=\"b3new-reveal\" data-target=\"b3ans7\">Lösung aufdecken</button><div class=\"b3new-answer\" id=\"b3ans7\" hidden><strong>39 %</strong><p>Diese Prognose motiviert einen lernorientierten Karriereplan. Nicht alle Skills werden verschwinden; viele werden ergänzt oder neu kombiniert.</p><small>Quelle: WEF Future of Jobs Report 2025</small></div></div></div></section>"},{"id":"b3x6-interview","title":"Interview-Training mit KI – aber kritisch","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · ÜBUNG</div><h1>Interview-Training mit KI – aber kritisch</h1><div class=\"b3new-body\"><div class=\"b3new-task\"><h2>10 Minuten · Tandem</h2><ol><li>Eine Person ist Recruiter, eine bewirbt sich auf die Musterstelle.</li><li>Fragt nach einem Projekt, einem Fehler und einer Situation mit Konflikten.</li><li>Antwortet konkret mit Situation – Aufgabe – Handlung – Ergebnis (STAR).</li><li>Gebt Feedback: Was war glaubwürdig, belegt und verständlich?</li></ol><p><strong>Optionaler KI-Prompt:</strong> „Spiele Recruiter für eine Junior-Product-Manager-Stelle. Stelle nacheinander fünf realistische Fragen und gib Feedback zur Belegbarkeit meiner Antworten. Erfinde keine Erfahrungen.“ Keine sensiblen Daten eingeben.</p></div></div></section>"},{"id":"b3x6-finale","title":"90-Tage-Karriereplan","html":"<section class=\"scene scene-inner b3new\"><div class=\"b3new-kicker\">BLOCK 3 · KAPITEL 6 · TRANSFER</div><h1>90-Tage-Karriereplan</h1><div class=\"b3new-body\"><div class=\"b3new-task\"><h2>10 Minuten · Abschluss</h2><ol><li>Wähle eine Zielrolle und die zwei wichtigsten Skill Gaps.</li><li>Definiere für Tag 30 einen kleinen Lernnachweis (z. B. Kursmodul oder Projektstart).</li><li>Definiere für Tag 60 ein sichtbares Ergebnis (Portfolio, Case Study, CV-Version).</li><li>Definiere für Tag 90 einen Markttest (Bewerbung, Feedbackgespräch oder Networking).</li></ol><p><strong>Take-away:</strong> Exportiere dein Career Cockpit und ergänze deinen Lebenslauf. Persönliche Unterlagen werden nicht eingesammelt.</p></div></div></section>"},{"id":"b3x1-kahoot","title":"Kahoot: Skills und Teamrollen","html":"<section class=\"scene-inner b3-scene\"><div class=\"eyebrow\">BLOCK 3 · KAPITEL 1 · ABSCHLUSS</div><h1>Kahoot: Skills, NovaWorks &amp; Teamrollen</h1><p class=\"lead\">15 mittelschwere Fragen · vier plausible Antworten · eine richtige Lösung pro Frage.</p><div class=\"b3new-grid\"><article class=\"b3new-card\"><h3>Was wird geprüft?</h3><p>Skill-based Hiring, Skill Gaps, Budgetentscheidungen, Qualität und Teamrollen nach Belbin.</p></article><article class=\"b3new-card\"><h3>So funktioniert es</h3><p>Die Lehrperson importiert den beigefügten Fragenkatalog in Kahoot. Die Studierenden spielen über die PIN.</p></article></div><p class=\"b3new-note\">Der vollständige Fragenkatalog mit Lösungen und Begründungen liegt im ZIP unter <strong>material/Kahoot_Block3_Kapitel1.csv</strong> und als lesbare TXT-Datei.</p></section>"}];
