// v1.2 – aufklappbare Musterlösung
document.querySelectorAll(".solution-toggle").forEach(btn=>{
  btn.addEventListener("click",e=>{
    e.stopPropagation();
    const box=btn.nextElementSibling;
    const willOpen=box.hasAttribute("hidden");
    if(willOpen) box.removeAttribute("hidden"); else box.setAttribute("hidden","");
    btn.textContent=willOpen?"Lösung / Einordnung verbergen":"Lösung / Einordnung anzeigen";
  });
});
document.querySelectorAll(".solution-box").forEach(box=>box.addEventListener("click",e=>e.stopPropagation()));

