document.getElementById("homeBtn")?.addEventListener("click",()=>go(0));
window.goToSceneId=(id)=>{const n=scenes.findIndex(s=>s.id===id);if(n>=0){closeSim();go(n);}};
document.querySelectorAll("[data-jump-scene]").forEach(b=>b.addEventListener("click",e=>{e.stopPropagation();window.goToSceneId(b.dataset.jumpScene);}));

// v1.7 robust controls
document.addEventListener("click",e=>{
 const sim=e.target.closest("#simulationBtn");
 if(sim){e.preventDefault();e.stopPropagation();document.getElementById("simulationPanel")?.classList.add("open");document.getElementById("simulationBackdrop")?.classList.add("open");document.getElementById("simulationPanel")?.setAttribute("aria-hidden","false");return;}
 const jump=e.target.closest("[data-jump-scene]");
 if(jump){e.preventDefault();e.stopPropagation();const n=scenes.findIndex(s=>s.id===jump.dataset.jumpScene);if(n>=0){closeSim();go(n);}}
});

/* v2.4 drawer behavior hardening */
(function(){
  const d=document.getElementById("drawer");
  const b=document.getElementById("drawerBackdrop");
  const menu=document.getElementById("menuBtn");
  const close=document.getElementById("drawerClose");
  if(!d) return;
  const openDrawer=()=>{d.classList.add("open"); if(b)b.classList.add("open");};
  const closeDrawer=()=>{d.classList.remove("open"); if(b)b.classList.remove("open");};
  if(menu) menu.onclick=openDrawer;
  if(close) close.onclick=closeDrawer;
  if(b) b.onclick=closeDrawer;
  d.addEventListener("click",(e)=>{
    if(e.target.closest(".nav-item[data-go]")) closeDrawer();
  });
  document.addEventListener("keydown",(e)=>{if(e.key==="Escape")closeDrawer();});
})();

