// v4.2 – Ausfallsichere Bilddarstellung auch ohne Internetverbindung.
// Externe Bilder können wegen Hotlink-Schutz, Netzfehlern oder CORS fehlen.
const FALLBACK_IMAGE='assets/visual/teamwork.jpg';
function repairBrokenImage(img){
  if(img.dataset.fallbackApplied==='1')return;
  img.dataset.fallbackApplied='1';
  const isPortrait=img.closest('.portrait-panel');
  img.src=isPortrait?'assets/visual/bergmann-concept.svg':FALLBACK_IMAGE;
  img.alt=isPortrait?'Grafische Darstellung: Frithjof Bergmanns New-Work-Konzept':'Illustration: Zusammenarbeit und New Work';
}
// capture=true catches error events from images added dynamically later.
document.addEventListener('error',event=>{
  if(event.target instanceof HTMLImageElement)repairBrokenImage(event.target);
},true);
// Handle images already failed before the listener was installed.
document.querySelectorAll('img').forEach(img=>{
  if(img.complete && img.naturalWidth===0)repairBrokenImage(img);
});


// Block 3 · local, privacy-friendly interactive teaching tools
(function(){
 function safe(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function cockpit(){
  const el=document.getElementById('b3-career-cockpit');if(!el||el.dataset.ready)return;el.dataset.ready='1';
  const fields=[['target','Meine Zielposition / Branche','text'],['evidence','Drei Kompetenzen mit konkreten Belegen','textarea'],['job','Anforderungen aus einer realen Stellenanzeige','textarea'],['gap','Meine zwei wichtigsten Skill Gaps','textarea'],['cv','Mein Lebenslauf: Was muss ich verbessern?','textarea'],['interview','Meine STAR-Erfolgsgeschichte (Situation, Task, Action, Result)','textarea'],['plan','Meine drei Schritte in den nächsten 90 Tagen','textarea']];
  el.innerHTML='<div class="b3new-form">'+fields.map(([id,label,type])=>'<label for="b3-'+id+'"><b>'+safe(label)+'</b>'+(type==='textarea'?'<textarea rows="2" id="b3-'+id+'" placeholder="Deine Notizen …"></textarea>':'<input type="text" id="b3-'+id+'" placeholder="Deine Notizen …">')+'</label>').join('')+'<div class="b3new-actions"><button class="b3new-action" type="button" id="b3-export">Cockpit als Textdatei speichern</button><button class="b3new-action secondary" type="button" id="b3-print">Druckansicht / PDF</button></div><p class="b3new-note">Nur lokale Verarbeitung im Browser. Keine Speicherung in der Lernwelt. Keine personenbezogenen Daten in öffentliche KI-Dienste kopieren.</p></div>';
  function content(){return 'MY FUTURE · CAREER COCKPIT\n\n'+fields.map(([id,label])=>label+'\n'+(el.querySelector('#b3-'+id)?.value||'')+'\n').join('\n')+'\nSelbstreflexion, keine automatisierte Eignungsbewertung.';}
  el.querySelector('#b3-export').onclick=()=>{const blob=new Blob([content()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Mein_Career_Cockpit.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  el.querySelector('#b3-print').onclick=()=>{const w=window.open('','_blank');if(!w){alert('Bitte Pop-ups für die Druckansicht erlauben.');return;}w.document.write('<!doctype html><html lang="de"><meta charset="utf-8"><title>Career Cockpit</title><body style="font:16px Arial;max-width:780px;margin:35px;white-space:pre-wrap">'+safe(content())+'</body></html>');w.document.close();w.focus();w.print();};
 }
 const obs=new MutationObserver(()=>{cockpit();});obs.observe(document.body,{childList:true,subtree:true});cockpit();
})();
